Object.assign(FIX, {
padthai:{list:["1 lb spaghetti or rice noodles (or 4 packs ramen, no flavor packets)","4 eggs","1 cup cooked chopped chicken (or 1/2 block tofu, cubed)","1 tablespoon peanut butter","1/4 cup soy sauce","Juice of 1 lime","2 tablespoons sugar","2 cups shredded cabbage","3 green onions, sliced","2 tablespoons oil"],
 steps:["Boil the noodles until just tender and drain.","Whisk the soy sauce, lime juice, sugar and peanut butter with 2 tablespoons hot water.","Heat the oil in a large skillet over medium high. Cook the chicken 2 minutes, then push aside and scramble the eggs.","Add the noodles, cabbage and sauce and toss 3 minutes until coated.","Top with green onion."]},
basilchicken:{list:["1 lb ground turkey, beef or pork","1 bunch fresh basil, leaves picked","3 tablespoons soy sauce","1 jalapeño, finely chopped","1 teaspoon sugar","1 teaspoon garlic powder","4 eggs","2 tablespoons oil","1 1/2 cups rice, with 3 cups water"],
 steps:["Cook the rice: bring the rice and water to a boil, cover and simmer on low 18 minutes.","Brown the meat in 1 tablespoon oil with the jalapeño and garlic, about 8 minutes.","Stir in the soy sauce and sugar, then the basil until just wilted.","Fry the eggs in the rest of the oil until the edges are crispy.","Serve the meat over rice with an egg on top."]},
lasagna:{list:["1 box (16 oz) lasagna noodles (about 12 noodles)","1 jar (24 oz) pasta sauce","1 lb ground beef or Italian sausage","1 cup cottage cheese","1 egg","2 cups shredded cheese","1 teaspoon Italian seasoning","1/2 cup water"],
 steps:["Heat oven to 375°F. Boil the noodles 2 minutes less than the box says and drain.","Brown the meat, drain, then stir in the sauce and water.","Mix the cottage cheese, egg and Italian seasoning.","In a 9x13 dish spread a little sauce, then layer noodles, cottage cheese mix, meat sauce and shredded cheese. Repeat 3 times.","Cover with foil and bake 30 minutes. Uncover and bake 15 minutes more.","Rest 10 minutes before cutting."]},
minestrone:{list:["4 oz small pasta","1 can (15 oz) kidney beans, drained","1 can (14 oz) diced tomatoes","2 carrots, diced","1 zucchini, diced","1/2 small onion, diced","6 cups chicken or vegetable broth","2 cups spinach","1 teaspoon Italian seasoning","1 tablespoon oil"],
 steps:["Cook the onion and carrot in the oil 6 minutes.","Add the tomatoes, broth, beans and Italian seasoning. Simmer 15 minutes.","Add the pasta and zucchini and cook 10 minutes.","Stir in the spinach until wilted."]},
aglio:{list:["1 lb spaghetti","1/3 cup oil","1 1/2 teaspoons garlic powder (or 6 cloves fresh garlic, sliced)","1/4 teaspoon red pepper flakes or chili powder","1/3 cup parmesan","2 tablespoons chopped parsley","1 tablespoon salt for the pasta water"],
 steps:["Boil the pasta in salted water. Save 1 cup of the water, then drain.","Warm the oil with the garlic and chili over low heat 2 minutes. Do not let it brown.","Add the pasta and 1/2 cup pasta water and toss until glossy.","Toss in the parmesan and parsley."]},
boxstroganoff:{list:["1 box (5.5 oz) beef stroganoff dinner kit","1 lb ground beef (or ground turkey)","Milk and hot water as the box says","1/4 cup sour cream","1 1/2 cups frozen peas"],
 steps:["Brown the beef in a large skillet and drain.","Stir in the milk, hot water, pasta and sauce mix from the box.","Bring to a boil, then cover and simmer as the box says, usually 10 to 12 minutes.","Stir in the sour cream.","Cook the peas and serve on the side."]},
stroganoff:{list:["1 lb ground beef","9 oz egg noodles","8 oz mushrooms, sliced","1/2 small onion, diced","2 tablespoons flour","2 cups beef or chicken broth","1 cup sour cream","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Boil the noodles and drain.","Brown the beef with the onion and mushrooms, about 10 minutes. Drain.","Sprinkle in the flour and stir 1 minute.","Stir in the broth, salt and pepper and simmer 5 minutes until thick.","Take off the heat, stir in the sour cream and serve over the noodles."]},
hamburgersteak:{list:["1 lb ground beef, shaped into 4 oval patties","1 large onion, sliced","2 tablespoons flour","2 cups beef broth","1/2 teaspoon salt","1/4 teaspoon pepper","1 1/3 cups instant mashed potato flakes, with water, milk and butter as the box says","1 can (14 oz) green beans"],
 steps:["Season the patties with salt and pepper and brown 4 minutes per side. Set aside.","Cook the onion in the drippings 6 minutes until soft.","Stir in the flour for 1 minute, then slowly whisk in the broth.","Return the patties, cover and simmer 10 minutes in the gravy.","Make the mashed potatoes and warm the green beans."]},
countrychicken:{list:["1 1/4 lb chicken breasts, pounded thin","1 egg","1 cup flour, plus 3 tablespoons for gravy","2 cups milk, plus 1/4 cup for the egg","1/4 cup oil","1 teaspoon salt","1/2 teaspoon pepper","1 1/3 cups instant mashed potato flakes, with water, milk and butter as the box says"],
 steps:["Beat the egg with 1/4 cup milk. Mix 1 cup flour with the salt and pepper.","Dip the chicken in flour, then egg, then flour again.","Fry in the oil over medium 4 to 5 minutes per side until golden and 165°F inside. Set aside.","Pour off all but 3 tablespoons oil. Whisk in 3 tablespoons flour for 1 minute, then slowly whisk in 2 cups milk. Simmer until thick and season with pepper.","Make the mashed potatoes and smother everything with gravy."]},
burgers:{list:["1 lb ground beef, made into 4 patties","4 hamburger buns","4 slices cheese","4 lettuce leaves (or sliced onion)","Ketchup and mustard","1/2 bag (32 oz) frozen fries","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Bake the fries as the bag says.","Press a small dent in the middle of each patty and season both sides with salt and pepper.","Cook in a hot skillet over medium high 4 minutes per side.","Add cheese for the last minute.","Toast the buns and build the burgers."]},
scratchmac:{list:["1 lb elbow macaroni","3 cups milk","4 tablespoons butter","1/4 cup flour","2 cups shredded cheese","1 cup diced ham","1 1/2 cups frozen peas","1/2 teaspoon salt"],
 steps:["Boil the macaroni, adding the peas for the last 2 minutes. Drain.","Melt the butter in the pot over medium. Whisk in the flour for 1 minute.","Slowly whisk in the milk and simmer 3 to 4 minutes until thick.","Take off the heat and stir in the cheese and salt until smooth.","Stir in the pasta, peas and ham."]},
tomatobasil:{list:["2 cans (14 oz each) diced tomatoes (or 2 cans tomato sauce)","1 cup chicken broth","1/2 cup milk or cream","1/2 bunch fresh basil, chopped","1 teaspoon sugar","1/2 teaspoon garlic powder","8 slices bread","8 slices cheese","4 tablespoons butter"],
 steps:["Simmer the tomatoes, broth, garlic and sugar 15 minutes.","Blend or mash until smooth. Stir in the milk and basil and keep warm.","Butter one side of each bread slice and build sandwiches with cheese inside.","Cook over medium 3 minutes per side until golden and melted.","Serve the grilled cheese with the soup."]},
caesarwrap:{list:["2 cups chopped cooked chicken (or 1 can chicken)","1 head romaine lettuce, chopped","1/3 cup parmesan","8 flour tortillas","1/3 cup mayo","Juice of 1 lemon","1/2 teaspoon garlic powder","1 cup croutons (or crushed crackers)"],
 steps:["Whisk the mayo, lemon juice, garlic powder and half the parmesan for the dressing.","Toss the lettuce, chicken, croutons and the rest of the parmesan with the dressing.","Spoon onto the tortillas and roll up tight.","Cut in half to serve."]},
musubi:{list:["1 can (12 oz) luncheon meat, sliced into 8 slices","1 1/2 cups short grain rice, with 2 cups water","4 nori sheets, cut in half","3 tablespoons soy sauce","2 tablespoons sugar"],
 steps:["Simmer the rice in the water, covered, 18 minutes. Rest 10 minutes.","Fry the slices in a skillet over medium 2 minutes per side.","Add the soy sauce and sugar and turn the slices until glazed and sticky.","Press rice into the cleaned can or with wet hands into a block the size of a slice.","Top with a slice of meat and wrap a nori strip around the middle. Wet the end to seal."]},
onigiri:{list:["1 1/2 cups short grain rice, with 2 cups water","2 cans (5 oz each) tuna, drained","3 tablespoons mayo","1 teaspoon soy sauce","4 nori sheets, cut into strips","1/2 teaspoon salt for your hands"],
 steps:["Simmer the rice in the water, covered, 18 minutes. Rest until warm enough to handle.","Mix the tuna, mayo and soy sauce.","Wet your hands and rub them with a little salt.","Flatten a handful of rice, add a spoonful of tuna, and press the rice around it into a triangle.","Wrap a strip of nori around the bottom."]},
blackbeansoup:{list:["3 cans (15 oz each) black beans, with liquid","1/2 small onion, diced","2 cups chicken or vegetable broth","1/2 cup salsa","1 teaspoon cumin","1 tablespoon oil","1/2 cup sour cream"],
 steps:["Cook the onion in the oil 5 minutes.","Add the beans with their liquid, broth, salsa and cumin. Simmer 15 minutes.","Mash or blend about half the soup until creamy.","Top bowls with sour cream."]},
bcburritos:{list:["8 flour tortillas","2 cans (16 oz each) refried beans","1 cup shredded cheese","1/2 cup salsa"],
 steps:["Warm the beans in a pot or the microwave.","Warm the tortillas.","Spread 1/3 cup beans on each, add cheese and salsa, fold the sides in and roll up.","Toast seam side down in a dry skillet over medium 2 minutes per side."]},
tunamelt:{list:["3 cans (5 oz each) tuna, drained","1/3 cup mayo","8 slices bread","8 slices cheese","3 tablespoons butter"],
 steps:["Mix the tuna and mayo.","Spread on 4 slices of bread, top with cheese and close with the other slices.","Butter the outsides.","Toast in a skillet over medium 3 minutes per side until golden and melted."]},
chilaquiles:{list:["1/2 bag (13 oz) tortilla chips","1 can (10 oz) red enchilada sauce (or 1 1/2 cups salsa)","4 eggs","1/2 cup shredded cheese","2 tablespoons diced onion","1/4 cup sour cream","1 tablespoon oil"],
 steps:["Warm the sauce in a large skillet over medium.","Add the chips and toss 1 minute until coated but still a little crunchy.","Fry the eggs in the oil in another pan.","Top the chips with eggs, cheese, onion and sour cream."]},
tamagoyaki:{list:["6 eggs","1 tablespoon sugar","2 teaspoons soy sauce","1 tablespoon oil","1 1/2 cups rice, with 3 cups water"],
 steps:["Cook the rice: bring the rice and water to a boil, cover and simmer on low 18 minutes.","Whisk the eggs, sugar and soy sauce.","Oil a nonstick pan over medium low. Pour in a thin layer of egg.","When almost set, roll it to one side. Oil the pan, add another thin layer, lift the roll so egg flows under, then roll it back up.","Repeat until the egg is used. Slice and serve with rice."]},
congee:{list:["1/2 cup rice","8 cups chicken broth","1/2 teaspoon ground ginger","4 eggs (or 1 cup cooked chicken)","3 green onions, sliced","2 tablespoons soy sauce"],
 steps:["Simmer the rice, broth and ginger, partly covered, about 1 hour, stirring now and then, until thick and creamy.","Soft boil the eggs 7 minutes, cool and peel.","Ladle into bowls and top with a halved egg, green onion and a drizzle of soy sauce."]},
masalaomelet:{list:["6 eggs","1/4 small onion, finely diced","1 tomato, diced","1 jalapeño, finely diced","1/2 teaspoon curry powder","1/4 bunch cilantro, chopped","1/4 teaspoon salt","1 tablespoon oil","4 slices bread or flatbread"],
 steps:["Whisk the eggs with the curry powder and salt.","Stir in the onion, tomato, jalapeño and cilantro.","Heat the oil in a nonstick pan over medium. Pour in half the eggs and cook until set, about 3 minutes.","Fold and slide out. Repeat with the rest. Serve with toast."]},
yogurtbowl:{list:["2 cups yogurt","2 tablespoons honey","1 cup granola (or 1/2 cup oats)","1 cup berries or 2 sliced bananas"],
 steps:["Spoon 1/2 cup yogurt into each bowl.","Top with fruit and granola.","Drizzle with honey."]},
kolaches:{list:["3 1/4 cups flour","1 packet (2 1/4 teaspoons) yeast","1 cup warm milk","4 tablespoons butter, melted","1 egg","3 tablespoons sugar","1/2 teaspoon salt","8 hot dogs or smoked sausage links","1/2 cup shredded cheese"],
 steps:["Stir the yeast and sugar into the warm milk. Let sit 5 minutes until foamy.","Mix in the butter, egg, salt and flour and knead 5 minutes into a soft dough. Cover and rise 1 hour.","Divide into 8 pieces. Flatten each, add a sprinkle of cheese and a sausage, and pinch the dough closed around it.","Set seam side down on a pan, cover and rise 30 minutes. Heat oven to 375°F.","Bake 15 to 18 minutes until golden."]},
rancheros:{list:["8 eggs","8 corn tortillas","1 can (16 oz) refried beans","3/4 cup salsa","1/2 cup shredded cheese","3 tablespoons oil"],
 steps:["Warm the beans.","Fry the tortillas in 2 tablespoons oil 20 seconds per side until soft. Drain on a towel.","Fry the eggs in the rest of the oil.","Spread beans on 2 tortillas per plate, top with eggs, salsa and cheese."]},
cinnamonrolls:{list:["3 1/2 cups flour","1 packet (2 1/4 teaspoons) yeast","1 cup warm milk, plus 3 tablespoons for glaze","6 tablespoons butter, softened and divided","1 egg","1/4 cup sugar","1/2 teaspoon salt","3/4 cup brown sugar","1 tablespoon cinnamon","1 cup powdered sugar (or regular sugar blended fine)"],
 steps:["Stir the yeast and sugar into the warm milk and let sit 5 minutes. Mix in 2 tablespoons butter, the egg, salt and flour. Knead 5 minutes. Cover and rise 1 hour.","Roll into a 12x16 inch rectangle. Spread with 4 tablespoons butter and sprinkle with the brown sugar and cinnamon.","Roll up from the long side and cut into 12 rolls. Set in a greased 9x13 pan, cover and rise 30 minutes.","Heat oven to 350°F. Bake 22 to 25 minutes until golden.","Stir the powdered sugar with 3 tablespoons milk and drizzle over the warm rolls."]},
queso:{list:["1 block (8 oz) cheese, shredded","1 can (10 oz) tomatoes and green chiles, drained","1/2 can (6 oz) evaporated milk","1 teaspoon flour","1/2 bag (13 oz) tortilla chips"],
 steps:["Toss the shredded cheese with the flour.","Warm the evaporated milk in a small pot over medium low until steaming.","Add the cheese a handful at a time, stirring until smooth.","Stir in the tomatoes and green chiles and serve warm with chips."]},
elote:{list:["2 cans (15 oz each) corn, drained","2 tablespoons butter","3 tablespoons mayo","Juice of 1 lime","1/2 teaspoon chili powder","1/2 cup crumbled cheese (feta or parmesan)"],
 steps:["Melt the butter in a skillet over medium high. Cook the corn 6 to 8 minutes until some kernels char.","Take off the heat and stir in the mayo, lime juice and chili powder.","Spoon into cups and top with cheese."]},
tzatziki:{list:["2 cups plain yogurt","1/2 cucumber, grated and squeezed dry","Juice of 1/2 lemon","1/2 teaspoon garlic powder","1 tablespoon chopped herbs","1/4 teaspoon salt","6 pita breads","2 tablespoons oil"],
 steps:["Stir the yogurt, cucumber, lemon juice, garlic, herbs and salt. Chill while you make the chips.","Heat oven to 375°F. Cut each pita into 8 wedges and brush with oil.","Bake 10 minutes until crisp.","Serve the chips with the dip."]},
chips:{list:["12 corn tortillas","2 tablespoons oil for baking (or 2 cups for frying)","1/2 teaspoon salt"],
 steps:["Cut each tortilla into 6 wedges.","To bake: heat oven to 375°F, brush with oil and bake 12 minutes, turning once.","To fry: heat 1 inch of oil to 350°F and fry in batches 1 to 2 minutes until crisp.","Salt right away."]},
eggrolls:{list:["1 package (12 oz) egg roll or dumpling wrappers","1/2 lb ground pork (or 1 can chicken)","3 cups shredded cabbage","2 carrots, shredded","2 tablespoons soy sauce","1/2 teaspoon ground ginger","Oil for frying (about 2 cups) or 2 tablespoons for baking"],
 steps:["Brown the pork in a skillet. Add the cabbage, carrot, soy sauce and ginger and cook 5 minutes until soft. Cool 10 minutes.","Put 2 tablespoons filling near one corner of a wrapper. Fold the corner over, fold in the sides and roll up. Seal with water.","Fry in 350°F oil 3 to 4 minutes until golden, or brush with oil and bake at 425°F for 15 minutes, turning once."]},
roastedchickpeas:{list:["2 cans (15 oz each) chickpeas, drained and patted very dry","2 tablespoons oil","1 teaspoon chili powder or paprika","1/2 teaspoon garlic powder","1/2 teaspoon salt"],
 steps:["Heat oven to 400°F.","Toss the chickpeas with the oil and spread on a sheet pan.","Roast 30 minutes, shaking the pan once, until crunchy.","Toss with the seasonings while hot. Cool to get extra crunchy."]},
smoothie:{list:["2 cups frozen berries (or 2 bananas, or 1 can fruit)","1 cup yogurt","1 cup milk or juice"],
 steps:["Add the milk and yogurt to the blender first, then the fruit.","Blend until smooth, adding a splash more milk if too thick.","Pour into 4 cups."]},
garlicknots:{list:["1 lb pizza dough","3 tablespoons butter, melted","1/2 teaspoon garlic powder","2 tablespoons parmesan","1/2 teaspoon Italian seasoning"],
 steps:["Heat oven to 400°F and line a pan with parchment.","Cut the dough into 12 pieces and roll each into a 6 inch rope.","Tie each rope in a loose knot and set on the pan.","Bake 15 minutes until golden.","Stir the butter and garlic and brush over the hot knots. Sprinkle with parmesan and Italian seasoning."]},
applepie:{list:["2 pie crusts","6 apples, peeled and sliced","3/4 cup sugar (white or brown)","2 tablespoons flour","1 teaspoon cinnamon","2 tablespoons butter"],
 steps:["Heat oven to 400°F.","Toss the apples with the sugar, flour and cinnamon.","Fit one crust into a pie pan and fill with the apples. Dot with butter.","Top with the second crust, pinch the edges together and cut 4 slits in the top.","Bake 45 to 50 minutes until golden and bubbling. Cool 2 hours before slicing."]},
sweetpotpie:{list:["1 pie crust","2 cups mashed cooked sweet potato (about 2 medium, or 1 can drained)","1 can (12 oz) evaporated milk","2 eggs","2 tablespoons butter, melted","3/4 cup sugar","1 teaspoon cinnamon","1 teaspoon vanilla"],
 steps:["Heat oven to 350°F.","Beat the sweet potato with the butter until smooth.","Beat in the evaporated milk, eggs, sugar, cinnamon and vanilla.","Pour into the crust.","Bake 55 to 60 minutes until the center is set. Cool before slicing."]},
pumpkinpie:{list:["1 pie crust","1 can (15 oz) pumpkin","1 can (14 oz) sweetened condensed milk","2 eggs","1 1/2 teaspoons cinnamon","1/4 teaspoon salt"],
 steps:["Heat oven to 425°F.","Whisk the pumpkin, condensed milk, eggs, cinnamon and salt until smooth.","Pour into the crust.","Bake 15 minutes, then lower to 350°F and bake 35 to 40 minutes until a knife comes out clean.","Cool before slicing."]},
bananacreampie:{list:["1 pie crust, baked (or 1 1/2 cups crushed graham crackers with 5 tablespoons melted butter)","2 boxes (3.4 oz each) vanilla instant pudding","3 cups cold milk","3 bananas, sliced"],
 steps:["Bake the crust as the package says and cool, or press the graham crumbs and butter into a pie pan and chill.","Whisk the pudding mix and cold milk 2 minutes until thick.","Layer banana slices in the crust and cover with half the pudding.","Add the rest of the bananas and pudding.","Chill 3 hours before slicing."]},
nochurn:{list:["2 cups (1 pint) heavy cream, very cold","1 can (14 oz) sweetened condensed milk","2 teaspoons vanilla","1 cup mix ins, such as berries, mashed banana or 1/4 cup cocoa"],
 steps:["Beat the cold cream until stiff peaks form, about 3 minutes with a mixer.","Gently fold in the condensed milk, vanilla and mix ins.","Spread in a loaf pan or glass dish and cover.","Freeze at least 6 hours."]},
blackberrycobbler:{list:["4 cups frozen berries","1 cup flour","1 cup sugar","1 cup milk","2 teaspoons baking powder","1 stick (1/2 cup) butter"],
 steps:["Heat oven to 350°F. Put the butter in a 9x9 dish and set it in the oven until melted.","Whisk the flour, sugar, baking powder and milk.","Pour over the butter. Do not stir.","Scatter the berries on top.","Bake 45 minutes until golden."]},
tresleches:{list:["1 cup flour","1 1/2 teaspoons baking powder","5 eggs","1 cup sugar","1/3 cup milk","1 teaspoon vanilla","1 can (12 oz) evaporated milk","1 can (14 oz) sweetened condensed milk","1/2 cup heavy cream (or milk)"],
 steps:["Heat oven to 350°F and grease a 9x13 dish.","Beat the eggs and sugar 5 minutes until pale and thick. Beat in the 1/3 cup milk and vanilla.","Gently fold in the flour and baking powder.","Bake 25 minutes until golden. Cool 15 minutes.","Poke holes all over with a fork. Mix the evaporated milk, condensed milk and cream and pour slowly over the cake.","Chill overnight."]},
churros:{list:["1 cup water","2 tablespoons butter","1 tablespoon sugar, plus 1/2 cup for rolling","1/4 teaspoon salt","1 cup flour","1 egg","1 teaspoon cinnamon","Oil for frying (about 3 cups)"],
 steps:["Boil the water, butter, 1 tablespoon sugar and salt. Stir in the flour until a ball forms. Cool 5 minutes.","Beat in the egg until smooth.","Spoon into a zip bag and snip the corner.","Pipe 4 inch strips into 350°F oil and fry 2 minutes per side until golden.","Roll in 1/2 cup sugar mixed with the cinnamon."]},
chocpudding:{list:["3 cups milk","1/2 cup sugar","1/3 cup cocoa powder","3 tablespoons flour (or cornstarch)","1 teaspoon vanilla","Pinch of salt"],
 steps:["Whisk the sugar, cocoa, flour and salt in a pot, then slowly whisk in the milk.","Cook over medium, stirring constantly, 8 to 10 minutes until thick.","Stir in the vanilla.","Pour into cups, cover and chill 2 hours."]},
sugarcookies:{list:["2 1/4 cups flour","1 stick (1/2 cup) butter, softened","1 cup sugar","1 egg","1 teaspoon vanilla","1 teaspoon baking powder","1/4 teaspoon salt"],
 steps:["Heat oven to 350°F.","Beat the butter and sugar until fluffy, then beat in the egg and vanilla.","Stir in the flour, baking powder and salt.","Roll into 1 inch balls and set 2 inches apart on a pan.","Bake 9 to 10 minutes until the edges just set."]},
poundcake:{list:["2 cups flour","2 sticks (1 cup) butter, softened","1 1/2 cups sugar","4 eggs","1/4 cup milk","1 teaspoon vanilla","1/4 teaspoon salt"],
 steps:["Heat oven to 325°F and grease a loaf pan.","Beat the butter and sugar 3 minutes until fluffy.","Beat in the eggs one at a time.","Mix in the flour and salt, then the milk and vanilla.","Bake 60 to 70 minutes until a toothpick comes out clean."]},
roastturkey:{list:["1 whole turkey, about 12 lb, fully thawed","1 stick (1/2 cup) butter, softened","1 medium onion, quartered","2 celery stalks, cut in pieces","2 carrots, cut in pieces","1 tablespoon poultry seasoning","1 tablespoon salt","1 teaspoon pepper"],
 steps:["Heat oven to 325°F. Take out the neck and giblets and pat the turkey dry.","Mix the butter, salt, pepper and poultry seasoning. Rub under and over the skin.","Put the onion, celery and carrot inside the turkey.","Roast in a pan about 15 minutes per pound, about 3 hours, until the thickest part of the thigh reads 165°F.","Rest 30 minutes before carving. Save the pan drippings for gravy."]},
turkeygravy:{list:["Pan drippings from the turkey","Butter as needed to make 1/4 cup fat (up to 4 tablespoons)","1/4 cup flour","3 cups chicken broth","1/2 teaspoon poultry seasoning","Salt and pepper to taste"],
 steps:["Pour the drippings into a pot. Skim off the fat and add butter to make 1/4 cup fat.","Whisk in the flour over medium and cook 2 minutes.","Slowly whisk in the broth and the poultry seasoning.","Simmer 5 minutes until thick. Season with salt and pepper."]},
cranberryjelly:{list:["Canned: 1 can (14 oz) jellied cranberry sauce","Homemade: 1 bag (12 oz) fresh cranberries","Homemade: 1 cup sugar","Homemade: 1 cup water"],
 steps:["Canned: chill the can, open both ends and slide it out. Slice into rounds.","Homemade: bring the sugar and water to a boil, add the cranberries and simmer 10 minutes until they pop.","Cool, then chill at least 2 hours. It thickens as it cools."]},
greenbeancasserole:{list:["3 cans (14 oz each) green beans, drained","1 can (10 oz) cream of chicken or mushroom soup","1/2 cup milk","1 teaspoon soy sauce","1 can (6 oz) crispy fried onions, divided","1/4 teaspoon pepper"],
 steps:["Heat oven to 350°F.","Mix the green beans, soup, milk, soy sauce, pepper and half the onions in a baking dish.","Bake 25 minutes until bubbly.","Top with the rest of the onions and bake 5 minutes more."]}
});
Object.assign(FIX, {
holidaymac:{list:["1 lb elbow macaroni","2 blocks (8 oz each) sharp cheddar, shredded (about 4 cups), divided","1 can (12 oz) evaporated milk","1/2 cup milk","2 eggs","4 tablespoons butter, cut into small pieces","1 teaspoon salt","1/2 teaspoon pepper","1/2 teaspoon garlic powder (optional)"],
 steps:["Heat oven to 350°F and grease a 9x13 baking dish.","Boil the macaroni in salted water 2 minutes less than the box says. Drain well.","Whisk the eggs, evaporated milk, milk, salt, pepper and garlic powder in a bowl.","Spread half the macaroni in the dish. Dot with half the butter and sprinkle with 1 1/2 cups cheese.","Add the rest of the macaroni, the rest of the butter and another 1 1/2 cups cheese.","Pour the egg mixture evenly over the top and finish with the last cup of cheese.","Bake uncovered 40 to 45 minutes until set in the middle and golden on top. Rest 10 minutes so it slices into squares."],tip:"Shred a block yourself. It melts creamier and costs less than bagged cheese."}
});
Object.assign(FIX, {
stuffing:{list:["1 loaf bread (about 16 slices), cut into 1 inch cubes","3 celery stalks, diced","1 medium onion, diced","1 stick (1/2 cup) butter","2 to 2 1/2 cups chicken broth","1 egg","2 teaspoons poultry seasoning","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Heat oven to 350°F. Spread the bread cubes on 2 sheet pans and bake 15 minutes until dry.","Melt the butter in a skillet and cook the celery and onion 8 minutes until soft.","In a big bowl, toss the bread with the vegetables, poultry seasoning, salt and pepper.","Whisk the egg into 2 cups broth and pour over, tossing until moist. Add more broth if dry.","Spread in a greased 9x13 dish. Bake covered 20 minutes, then uncovered 15 minutes until crisp on top."]},
cornbreaddressing:{list:["2 boxes (8.5 oz each) corn muffin mix, baked and crumbled (or a 9x13 pan of scratch cornbread)","6 slices bread, torn","3 celery stalks, diced","1 medium onion, diced","4 tablespoons butter","3 to 4 cups chicken broth","2 eggs","2 teaspoons poultry seasoning","1/2 teaspoon pepper"],
 steps:["Bake the cornbread a day ahead if you can. Crumble it with the torn bread into a big bowl.","Cook the celery and onion in the butter 8 minutes until soft and add to the bowl.","Whisk the eggs, poultry seasoning, pepper and 3 cups broth and pour over. Stir until very moist, like thick oatmeal. Add more broth if needed.","Spread in a greased 9x13 dish.","Bake at 350°F for 45 minutes until golden and set."]},
garlicmash:{list:["5 lb bag potatoes (use about 2 1/2 lb, 5 medium), peeled and cut into chunks","4 tablespoons butter","3/4 cup milk, warmed","1 teaspoon garlic powder","1 teaspoon salt, plus more for the water","1/4 teaspoon pepper"],
 steps:["Cover the potatoes with cold salted water and bring to a boil.","Simmer 15 to 18 minutes until a fork slides in easily.","Drain well and return to the pot for 1 minute to dry.","Mash with the butter, then stir in the warm milk, garlic powder, salt and pepper until creamy."]},
candiedyams:{list:["3 medium sweet potatoes, cooked, peeled and sliced (or 2 cans yams, drained)","3/4 cup brown sugar, divided","6 tablespoons butter, divided","1 teaspoon cinnamon","1/2 cup oats","2 tablespoons flour"],
 steps:["Heat oven to 375°F. Lay the sweet potato slices in a baking dish.","Melt 4 tablespoons butter with 1/2 cup brown sugar and the cinnamon and pour over.","Mix the oats, flour, the rest of the brown sugar and 2 tablespoons soft butter into a crumble.","Sprinkle over the top.","Bake 30 minutes until bubbly and golden."]},
corncasserole:{list:["1 can (15 oz) corn, drained","1 can (14.75 oz) creamed corn","1 box (8.5 oz) corn muffin mix","1 cup sour cream","1 stick (1/2 cup) butter, melted","1 egg"],
 steps:["Heat oven to 350°F and grease an 8x8 dish.","Stir everything together in a bowl.","Pour into the dish.","Bake 45 minutes until golden and set in the middle."]},
glazedham:{list:["1 spiral cut ham, about 8 lb","1 cup brown sugar","2 tablespoons mustard","1/4 cup honey (or orange juice)","1/2 teaspoon cinnamon","1/2 cup water"],
 steps:["Heat oven to 325°F. Set the ham cut side down in a roasting pan, add the water and wrap tightly in foil.","Bake 10 minutes per pound, about 80 minutes.","Simmer the brown sugar, mustard, honey and cinnamon 3 minutes into a glaze.","Unwrap the ham, brush with half the glaze and bake 10 minutes. Brush again and bake 10 minutes more."]},
scalloped:{list:["5 medium potatoes, sliced very thin","1/2 small onion, thinly sliced","4 tablespoons butter","1/4 cup flour","3 cups milk","1 1/2 cups shredded cheese, divided","1 teaspoon salt","1/2 teaspoon garlic powder","1/4 teaspoon pepper"],
 steps:["Heat oven to 375°F and grease a 9x13 dish.","Melt the butter in a pot, whisk in the flour 1 minute, then slowly whisk in the milk. Simmer until thick. Stir in the salt, garlic, pepper and 1 cup cheese.","Layer a third of the potatoes and onion in the dish, then a third of the sauce. Repeat twice.","Cover with foil and bake 45 minutes.","Uncover, add the rest of the cheese and bake 20 minutes until tender and golden."]},
honeycarrots:{list:["2 lb carrots, peeled and cut into sticks","2 tablespoons butter, melted","2 tablespoons honey","1/2 teaspoon salt"],
 steps:["Heat oven to 425°F and line a sheet pan with foil.","Toss the carrots with the butter, honey and salt.","Spread out in one layer.","Roast 25 to 30 minutes, stirring once, until tender and caramelized."]},
tamales:{list:["1 bag (8 oz) corn husks (about 30)","3 lb pork shoulder, cut into chunks","2 cans (10 oz each) red enchilada sauce","1 tablespoon chili powder","1 teaspoon cumin","4 cups masa harina","1 cup oil (or lard)","1 teaspoon baking powder","1 1/2 teaspoons salt","About 3 cups warm chicken broth"],
 steps:["Simmer the pork in water to cover for 2 hours until it shreds. Shred and mix with the enchilada sauce, chili powder and cumin.","Soak the husks in hot water 30 minutes.","Beat the masa, oil, baking powder and salt, adding warm broth a little at a time, until soft and fluffy like thick frosting.","Spread 2 to 3 tablespoons masa on the wide end of each husk, add a spoonful of pork, fold in the sides and fold up the bottom.","Stand them open end up in a steamer pot with water below. Cover and steam 1 1/2 hours, adding water as needed, until the masa pulls away from the husk."],tip:"Make it a family day. Tamales freeze great."},
gingerbread:{list:["3 cups flour","3/4 cup brown sugar","1 stick (1/2 cup) butter, softened","1 egg","1/2 cup molasses","1 teaspoon baking powder","1 tablespoon ground ginger","1 teaspoon cinnamon","1/4 teaspoon salt"],
 steps:["Beat the butter and brown sugar until fluffy. Beat in the egg and molasses.","Stir in the flour, baking powder, ginger, cinnamon and salt.","Wrap the dough and chill 1 hour.","Heat oven to 350°F. Roll the dough 1/4 inch thick on a floured counter and cut shapes.","Bake 8 to 10 minutes. Cool before decorating."]},
monkeybread:{list:["2 cans (8 count each) biscuits","1/2 cup sugar","2 teaspoons cinnamon","1 stick (1/2 cup) butter","1/2 cup brown sugar"],
 steps:["Heat oven to 350°F and grease a Bundt or 9x9 pan.","Cut each biscuit into 4 pieces.","Shake the pieces in a bag with the sugar and cinnamon and pile into the pan.","Melt the butter with the brown sugar and pour over.","Bake 30 to 35 minutes. Cool 5 minutes and flip onto a plate."]},
hotcocoa:{list:["4 cups milk","1/3 cup cocoa powder","1/3 cup sugar","1/4 cup hot water","1 teaspoon vanilla","Pinch of salt"],
 steps:["Whisk the cocoa, sugar, salt and hot water in a pot into a smooth paste.","Whisk in the milk.","Heat over medium, stirring, until steaming. Do not boil.","Stir in the vanilla and pour into mugs."]},
hoppinjohn:{list:["1 lb dry black eyed peas, soaked overnight (or 3 cans, drained)","1 smoked ham hock (or 1/2 lb diced ham)","1 1/2 cups long grain rice, with 3 cups water","1 medium onion, diced","2 celery stalks, diced","1 bell pepper, diced","1 tablespoon Cajun seasoning","6 cups chicken broth"],
 steps:["Simmer the peas, ham hock, onion, celery and pepper in the broth 1 hour until tender. With canned peas, simmer 20 minutes.","Take out the hock, pull off the meat and stir it back in.","Season with Cajun seasoning.","Cook the rice: bring the rice and water to a boil, cover and simmer on low 18 minutes.","Serve the peas over the rice."],tip:"Eaten on New Year's Day for good luck."},
bepsoup:{list:["3 cans (15 oz each) black eyed peas, drained","1 package (13 oz) smoked sausage, sliced","1 can (14 oz) diced tomatoes","1 medium onion, diced","2 carrots, diced","6 cups chicken broth","3 cups chopped spinach or collards","1 teaspoon Cajun seasoning"],
 steps:["Brown the sausage with the onion and carrot in a big pot, about 8 minutes.","Add the peas, tomatoes, broth and Cajun seasoning.","Simmer 30 minutes.","Stir in the greens and cook until wilted."]},
smotheredcabbage:{list:["1 head cabbage, cored and chopped","6 slices bacon, chopped (or 1/2 package smoked sausage)","1/2 small onion, diced","2 tablespoons butter","1/2 cup chicken broth","1/2 teaspoon garlic powder","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Cook the bacon in a large pot over medium until crisp. Add the onion and cook 3 minutes.","Add the cabbage, butter, garlic, salt, pepper and broth.","Cover and cook on low 30 minutes, stirring now and then, until very tender."]},
collardgreens:{list:["2 bunches collard greens, washed, stems removed, sliced","1 smoked ham hock (or 6 slices bacon)","1/2 small onion, diced","6 cups chicken broth","2 tablespoons vinegar","1 teaspoon sugar","1/2 teaspoon red pepper flakes or chili powder","Salt to taste"],
 steps:["Simmer the ham hock in the broth 30 minutes.","Add the greens, onion, vinegar, sugar and pepper flakes.","Cover and simmer 1 hour until tender.","Pull the meat off the hock, stir it in and season with salt."]},
hamcabbagesoup:{list:["1/2 lb ham steak, diced (or 1 ham hock)","1/2 head cabbage, chopped","2 carrots, diced","2 potatoes, diced","1/2 small onion, diced","8 cups chicken broth","1/2 teaspoon garlic powder","1 tablespoon oil"],
 steps:["Cook the onion and carrot in the oil 5 minutes.","Add the ham, cabbage, potatoes, broth and garlic powder.","Simmer 30 minutes until the potatoes and cabbage are tender."]},
skilletcornbread:{list:["1 1/2 cups cornmeal","1/2 cup flour","1 tablespoon baking powder","1 tablespoon sugar","3/4 teaspoon salt","1 egg","1 1/2 cups buttermilk (or milk)","4 tablespoons butter, divided"],
 steps:["Put 2 tablespoons butter in a cast iron skillet and set it in the oven. Heat to 425°F.","Mix the cornmeal, flour, baking powder, sugar and salt.","Whisk in the egg, buttermilk and the other 2 tablespoons butter, melted.","Pour into the hot buttered skillet. It should sizzle.","Bake 20 minutes until golden."]},
porkkraut:{list:["3 lb pork shoulder (or 1 1/2 lb pork chops)","2 jars (14 oz each) sauerkraut, drained","1 apple, sliced","1 medium onion, sliced","2 tablespoons brown sugar","1 cup water","1 tablespoon oil","1 teaspoon salt","1 1/3 cups instant mashed potato flakes, with water, milk and butter as the box says"],
 steps:["Heat oven to 325°F. Salt the pork and brown it on all sides in the oil in an oven safe pot.","Add the sauerkraut, apple, onion, brown sugar and water around the pork.","Cover and bake 2 1/2 hours until the pork is tender. Chops need about 1 hour.","Make the mashed potatoes and serve together."],tip:"A Pennsylvania New Year's tradition for luck."},
chickengyros:{list:["1 1/2 lb chicken thighs, sliced","1 1/2 cups plain yogurt, divided","Juice of 1 lemon, divided","2 tablespoons oil","1 teaspoon Italian seasoning","1 teaspoon garlic powder, divided","1/2 teaspoon salt","6 pita breads","1/2 cucumber, grated and squeezed dry","1 1/2 tomatoes, sliced","1/2 small onion, sliced"],
 steps:["Toss the chicken with 1/2 cup yogurt, half the lemon juice, the oil, Italian seasoning, 1/2 teaspoon garlic and salt. Rest 30 minutes.","Sear in a hot skillet over medium high 8 to 10 minutes until charred and done.","Stir 1 cup yogurt with the cucumber, the rest of the garlic and lemon for tzatziki.","Warm the pitas and fill with chicken, tomato, onion and tzatziki."]},
cuketomato:{list:["1 cucumber, chopped","3 tomatoes, chopped","1/4 small red onion, thinly sliced","1/4 cup crumbled feta","Juice of 1/2 lemon","2 tablespoons oil","1/2 teaspoon Italian seasoning","1/4 teaspoon salt"],
 steps:["Put the cucumber, tomato and onion in a bowl.","Whisk the lemon juice, oil, Italian seasoning and salt.","Toss with the vegetables.","Top with feta."]},
honeyhummus:{list:["1 can (15 oz) chickpeas, drained (save 1/4 cup liquid)","Juice of 1 lemon","3 tablespoons oil, plus more to drizzle","1/2 teaspoon garlic powder","1/2 teaspoon salt","2 tablespoons honey","1/4 teaspoon chili powder or red pepper flakes","6 pita breads or a sleeve of crackers"],
 steps:["Blend the chickpeas, lemon juice, oil, garlic and salt, adding the saved liquid until very smooth.","Warm the honey with the chili for 15 seconds in the microwave.","Swirl the hummus into a bowl and drizzle with the hot honey and a little oil.","Serve with pita or crackers."]},
firefeta:{list:["1 block (8 oz) feta (or two 4 oz blocks)","1 can (14 oz) diced tomatoes, drained (or 2 tomatoes, chopped)","2 tablespoons oil","1/4 teaspoon red pepper flakes or chili powder","1/2 teaspoon Italian seasoning","1 tablespoon honey","6 pita breads or a loaf of bread"],
 steps:["Heat oven to 400°F.","Set the feta in a small baking dish and spoon the tomatoes around it.","Drizzle with oil and sprinkle with chili and Italian seasoning.","Bake 20 minutes until soft and bubbling.","Drizzle with honey and scoop with warm pita."]},
redpepperhummus:{list:["1 can (15 oz) chickpeas, drained","1/2 jar (6 oz) roasted red peppers, drained","Juice of 1 lemon","3 tablespoons oil","1/2 teaspoon garlic powder","1/4 teaspoon chili powder","1/2 teaspoon salt","Pita, carrots or crackers for dipping"],
 steps:["Blend everything except the dippers until smooth.","Add a splash of water if too thick.","Taste and add salt or lemon.","Serve with pita, carrots or crackers."]},
spanakopita:{list:["1 box (16 oz) phyllo dough, thawed","2 bags (12 oz each) frozen spinach, thawed and squeezed very dry","2 packages (4 oz each) feta, crumbled","2 eggs","1/2 small onion, finely diced and cooked soft","1/4 cup chopped herbs (dill or parsley)","1 stick (1/2 cup) butter, melted"],
 steps:["Heat oven to 375°F and butter a 9x13 dish.","Mix the spinach, feta, eggs, cooked onion and herbs.","Lay in 8 sheets of phyllo one at a time, brushing each with butter.","Spread the filling over, then top with 8 more buttered sheets.","Score the top into squares and bake 40 minutes until golden."],tip:"Keep phyllo under a damp towel so it does not dry out."},
pastitsio:{list:["1 lb pasta (penne or elbow)","1 lb ground beef (or ground turkey)","1 can (8 oz) tomato sauce","1/2 teaspoon cinnamon","4 tablespoons butter","1/4 cup flour","3 cups milk","1 egg","1/2 cup parmesan","1/2 teaspoon salt"],
 steps:["Heat oven to 350°F. Boil the pasta 2 minutes less than the box says and drain.","Brown the beef, drain, then simmer with the tomato sauce, cinnamon and salt 10 minutes.","Melt the butter, whisk in the flour 1 minute, then slowly whisk in the milk and simmer until thick. Off the heat whisk in the egg and half the parmesan.","Layer half the pasta in a 9x13 dish, then the meat, then the rest of the pasta. Pour the white sauce over and sprinkle with the rest of the parmesan.","Bake 40 minutes until golden. Rest 15 minutes before cutting."]},
moussaka:{list:["2 eggplants, sliced 1/2 inch thick","2 potatoes, sliced thin","1 lb ground beef (or ground turkey)","1/2 small onion, diced","1 can (8 oz) tomato sauce","1/2 teaspoon cinnamon","3 tablespoons oil","4 tablespoons butter","1/4 cup flour","3 cups milk","1 egg","1/2 teaspoon salt"],
 steps:["Heat oven to 400°F. Brush the eggplant and potato slices with oil and roast on pans 20 minutes.","Brown the beef with the onion, drain, then simmer with the tomato sauce, cinnamon and salt 10 minutes.","Make the white sauce: melt the butter, whisk in the flour, then the milk, and simmer until thick. Whisk in the egg off the heat.","In a 9x13 dish layer the potatoes, half the eggplant, the meat, then the rest of the eggplant. Pour the sauce on top.","Lower the oven to 350°F and bake 40 minutes. Rest 15 minutes."]},
avgolemono:{list:["1 lb chicken thighs (or 1 can chicken)","1/2 cup rice (or orzo)","8 cups chicken broth","2 eggs","Juice of 2 lemons","1/2 teaspoon salt"],
 steps:["Simmer the chicken and rice in the broth 20 minutes until tender. Shred the chicken.","Whisk the eggs and lemon juice in a bowl.","Slowly whisk 2 ladles of hot broth into the eggs so they warm without scrambling.","Turn off the heat and stir the egg mixture back into the pot. It turns silky and creamy.","Season with salt."]},
lemonrice:{list:["1 1/2 cups long grain rice","3 cups chicken broth","Juice of 1 1/2 lemons","1/2 small onion, diced","1 tablespoon butter","2 tablespoons chopped herbs"],
 steps:["Melt the butter in a pot and cook the onion 4 minutes.","Stir in the rice for 1 minute.","Add the broth and lemon juice and bring to a boil.","Cover and simmer on low 18 minutes. Rest 5 minutes, then fluff with the herbs."]},
orzosalad:{list:["8 oz orzo (half a box)","1 cucumber, diced","2 tomatoes, diced","1/3 cup kalamata olives, sliced","1/2 cup crumbled feta","Juice of 1 lemon","3 tablespoons oil","1 teaspoon Italian seasoning","1/4 teaspoon salt"],
 steps:["Boil the orzo 9 minutes, drain and rinse with cold water.","Toss with the cucumber, tomato, olives and feta.","Whisk the lemon, oil, Italian seasoning and salt and pour over.","Chill until ready to eat."]},
falafel:{list:["2 cans (15 oz each) chickpeas, drained and patted dry","1/2 small onion","1/2 bunch parsley or cilantro","1/4 cup flour","1 teaspoon cumin","1 teaspoon garlic powder","1/2 teaspoon salt","3 tablespoons oil","6 pita breads","1 cup yogurt mixed with a squeeze of lemon","1/2 cucumber and 1 1/2 tomatoes, chopped"],
 steps:["Heat oven to 400°F and oil a sheet pan.","Pulse the chickpeas, onion, herbs, flour, cumin, garlic and salt until it holds together but is not smooth.","Shape into 16 small patties, set on the pan and brush with oil.","Bake 25 minutes, flipping halfway, until crisp.","Stuff pitas with falafel, cucumber, tomato and yogurt sauce."]},
shawarma:{list:["2 lb chicken thighs","2 tablespoons oil","1 teaspoon cumin","1 teaspoon curry powder","1 teaspoon garlic powder, divided","Juice of 1 lemon, divided","1/2 teaspoon salt","1 1/2 cups rice, with 3 cups water","1 cup yogurt","1/2 cucumber and 1 1/2 tomatoes, chopped"],
 steps:["Toss the chicken with the oil, cumin, curry powder, 1/2 teaspoon garlic, half the lemon and salt.","Roast on a sheet pan at 425°F for 25 minutes until charred. Slice thin.","Cook the rice: bring the rice and water to a boil, cover and simmer on low 18 minutes.","Stir the yogurt with the rest of the garlic and lemon.","Build bowls with rice, chicken, cucumber, tomato and garlic yogurt."]},
kofta:{list:["1 lb ground beef","1/2 small onion, grated","2 tablespoons chopped herbs","1 teaspoon cumin","1/4 teaspoon cinnamon","1/2 teaspoon salt","1 1/2 cups rice, with 3 cups water (or 6 pitas)","1 cup yogurt","1/2 cucumber, grated"],
 steps:["Mix the beef, onion, herbs, cumin, cinnamon and salt with your hands.","Shape into 8 logs around skewers or just as logs.","Cook in a hot skillet or under the broiler 10 minutes, turning, until browned and done.","Stir the yogurt and cucumber for sauce.","Serve with rice or pita."]},
keftedes:{list:["1 lb ground beef (or ground turkey)","2 slices bread, soaked in water and squeezed (or 1/2 sleeve crushed crackers)","1 egg","1/2 small onion, grated","2 tablespoons chopped herbs","1 teaspoon Italian seasoning","1/2 teaspoon salt","3 tablespoons oil","1 lemon","1 cup yogurt"],
 steps:["Mix the beef, bread, egg, onion, herbs, Italian seasoning and salt.","Roll into 1 inch balls.","Fry in the oil over medium 8 to 10 minutes, turning, until browned and cooked through.","Squeeze lemon over and serve with yogurt."]},
greekpotatoes:{list:["5 medium potatoes, cut into wedges","Juice of 1 1/2 lemons","1/4 cup oil","1 teaspoon Italian seasoning","1 teaspoon garlic powder","1 teaspoon salt","1 cup chicken broth"],
 steps:["Heat oven to 425°F.","Toss the potatoes with the lemon, oil, Italian seasoning, garlic and salt in a baking dish.","Pour the broth into the dish.","Roast 50 minutes, turning once, until golden and the liquid is absorbed."]},
fasolada:{list:["2 cans (15 oz each) butter beans, drained","2 carrots, sliced","2 celery stalks, sliced","1/2 small onion, diced","1 can (8 oz) tomato sauce","4 cups water","1/4 cup oil","1 teaspoon Italian seasoning","1/2 teaspoon salt"],
 steps:["Cook the onion, carrot and celery in the oil 8 minutes.","Add the beans, tomato sauce, water, Italian seasoning and salt.","Simmer 30 minutes.","Drizzle with a little more oil to serve."]},
gigantes:{list:["3 cans (15 oz each) butter beans, drained","1 can (14 oz) diced tomatoes","1/2 small onion, diced","2 tablespoons chopped herbs","1/4 cup crumbled feta","1 teaspoon Italian seasoning","1/2 teaspoon garlic powder","3 tablespoons oil"],
 steps:["Heat oven to 375°F.","Cook the onion and garlic in the oil 5 minutes. Add the tomatoes and Italian seasoning and simmer 10 minutes.","Stir in the beans and herbs and pour into a baking dish.","Top with feta and bake 30 minutes."]},
dolmas:{list:["1 jar (16 oz) grape leaves, rinsed","1 cup long grain rice","1/2 small onion, finely diced","1/2 bunch herbs, chopped","Juice of 2 lemons, divided","1/3 cup oil","1/2 teaspoon salt","About 3 cups water"],
 steps:["Cook the onion in half the oil 5 minutes. Stir in the rice, herbs, half the lemon and salt.","Lay a leaf shiny side down, add 1 tablespoon filling, fold in the sides and roll tight.","Pack seam side down in a pot lined with a few torn leaves.","Pour over the rest of the oil and lemon and enough water to cover. Set a plate on top.","Simmer covered 45 minutes until the rice is tender."]},
greeksheetpan:{list:["1 1/2 lb chicken thighs or breasts, cut into chunks","1 zucchini (or 2 bell peppers), chopped","1/2 small onion, cut in wedges","1 1/2 tomatoes, chopped","1/4 cup crumbled feta","Juice of 1 lemon","2 tablespoons oil","1 teaspoon Italian seasoning","1/2 teaspoon garlic powder","1/2 teaspoon salt"],
 steps:["Heat oven to 425°F.","Toss the chicken and vegetables with the lemon, oil, Italian seasoning, garlic and salt.","Spread on a sheet pan.","Roast 30 minutes until the chicken is done.","Top with feta."]},
medpasta:{list:["1 lb pasta","1 can (14 oz) diced tomatoes","1/3 cup kalamata olives, sliced","2 cups spinach","1/2 cup crumbled feta (or parmesan)","3 tablespoons oil","1/2 teaspoon garlic powder","1 teaspoon Italian seasoning"],
 steps:["Boil the pasta and save 1/2 cup of the water.","Warm the oil, tomatoes, olives, garlic and Italian seasoning in a skillet 5 minutes.","Add the spinach until wilted.","Toss with the pasta, a splash of pasta water and the feta."]},
loukoumades:{list:["2 cups flour","1 packet (2 1/4 teaspoons) yeast","1 tablespoon sugar","1 1/4 cups warm water","1/4 teaspoon salt","1/2 cup honey","1 teaspoon cinnamon","Oil for frying (about 3 cups)"],
 steps:["Stir the yeast and sugar into the warm water. Mix in the flour and salt into a loose, sticky batter.","Cover and rise 1 hour until bubbly.","Heat 2 inches of oil to 350°F. Drop in spoonfuls of batter and fry 3 to 4 minutes, turning, until golden.","Warm the honey and drizzle over the donuts. Sprinkle with cinnamon."]},
yogurtcake:{list:["2 cups flour","2 teaspoons baking powder","1 cup plain yogurt","3 eggs","1 cup sugar","1/2 cup oil","Zest and juice of 1 lemon","1/4 teaspoon salt"],
 steps:["Heat oven to 350°F and grease a loaf pan.","Whisk the yogurt, eggs, sugar, oil, lemon zest and juice.","Fold in the flour, baking powder and salt.","Pour into the pan and bake 45 to 50 minutes until a toothpick comes out clean."]},
burgerbowl:{list:["1 lb ground beef (or ground turkey)","1/2 head lettuce, chopped","1 1/2 tomatoes, diced","3/4 cup shredded cheese","1/2 small onion, diced","2 tablespoons mayo","1 tablespoon ketchup","1 teaspoon mustard","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Brown the beef with the salt and pepper, about 8 minutes. Drain.","Stir the mayo, ketchup and mustard into a burger sauce.","Pile lettuce in bowls and top with beef, cheese, tomato and onion.","Drizzle with the sauce."]},
caulifriedrice:{list:["2 bags (12 oz each) frozen riced cauliflower","3 eggs","1/2 lb ham steak, diced (or 4 slices bacon)","3 green onions, sliced","3 tablespoons soy sauce","1/2 teaspoon garlic powder","2 tablespoons oil"],
 steps:["Cook the ham in 1 tablespoon oil over medium high 3 minutes.","Add the cauliflower and cook 6 to 8 minutes until hot and a little browned.","Push aside, add the rest of the oil and scramble the eggs.","Stir everything together with the soy sauce, garlic and green onion."]},
zucchiniboats:{list:["2 zucchini","1/2 lb ground beef or Italian sausage","1 1/4 cups pasta sauce","1 cup shredded cheese","2 tablespoons parmesan","1 teaspoon Italian seasoning"],
 steps:["Heat oven to 400°F.","Halve the zucchini lengthwise and scoop out the middles with a spoon. Chop the middles.","Brown the meat, drain, then stir in the sauce, chopped zucchini and Italian seasoning.","Set the boats in a baking dish, fill with the meat sauce and top with both cheeses.","Bake 20 minutes until the zucchini is tender."]},
fajitabowl:{list:["2 lb chicken thighs (or breasts), sliced","3 bell peppers, sliced (or 1 bag frozen peppers)","1 medium onion, sliced","1/2 head lettuce, shredded","1/2 cup salsa","1/2 cup sour cream","1 packet (1 oz) taco seasoning","2 tablespoons oil"],
 steps:["Toss the chicken with the taco seasoning.","Cook in 1 tablespoon oil over high 7 to 8 minutes until done. Set aside.","Add the rest of the oil and cook the peppers and onion 5 to 6 minutes until charred.","Serve over lettuce with salsa and sour cream."]},
cbrwraps:{list:["1 1/2 lb chicken breast, cooked and chopped (or 2 cans chicken)","6 slices bacon","1 head lettuce, leaves separated","1/3 cup ranch","1/2 cup shredded cheese","1 tomato, diced"],
 steps:["Cook the bacon until crisp and crumble.","Season and cook the chicken in a skillet 6 to 8 minutes per side, then chop. Or use canned chicken.","Toss the chicken with ranch, bacon and cheese.","Spoon into lettuce leaves and top with tomato."]},
tunaavocado:{list:["2 cans (5 oz each) tuna, drained","2 avocados","3 tablespoons mayo","1 celery stalk, finely diced","Juice of 1 lemon","1/4 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Halve the avocados and remove the pits. Squeeze a little lemon over them.","Mix the tuna, mayo, celery, the rest of the lemon, salt and pepper.","Pile the tuna into the avocado halves."]}
});

Object.assign(FIX, {
chesspie:{list:["1 unbaked 9 inch pie crust","1 1/2 cups sugar","1/2 cup (1 stick) butter, melted","4 large eggs","1 tablespoon cornmeal","1/4 cup milk (or evaporated milk)","1 teaspoon vanilla extract","1/4 teaspoon salt"],
 steps:["Heat oven to 350°F. Set the pie crust in a 9 inch pie pan.","In a bowl, whisk the 1 1/2 cups sugar, 1 tablespoon cornmeal and 1/4 teaspoon salt.","Whisk in the 1/2 cup melted butter, then the 4 eggs one at a time.","Stir in the 1/4 cup milk and 1 teaspoon vanilla until smooth.","Pour into the crust and bake 45 to 50 minutes, until the top is golden and the center only jiggles a little.","Cool at least 1 hour before slicing so it sets."]},
crustlesspizza:{list:["1/2 lb Italian sausage (or ground beef)","3 oz sliced pepperoni (about half a bag)","1 1/4 cups pasta sauce","2 cups shredded mozzarella or pizza cheese, divided","4 oz mushrooms, sliced (or 1 bell pepper, chopped)","1 teaspoon Italian seasoning"],
 steps:["Heat oven to 400°F.","Brown the 1/2 lb sausage in a skillet over medium heat for 6 to 8 minutes, breaking it up. Drain the grease.","Spread the sausage in an 8x8 baking dish.","Spoon the 1 1/4 cups sauce over it and sprinkle with the 1 teaspoon Italian seasoning.","Add the mushrooms, then 1 cup cheese, then the pepperoni, then the last 1 cup cheese.","Bake 15 to 18 minutes until bubbly and browned on top."]},
caulimash:{list:["2 bags (12 oz each) frozen riced cauliflower","2 tablespoons butter","2 oz cream cheese (1/4 of a block)","1/4 cup grated parmesan","1/2 teaspoon garlic powder","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Microwave both bags of cauliflower as the bag says, or steam for 8 to 10 minutes, until very soft.","Drain well, then press with a spoon or squeeze in a towel to get the extra water out.","Mash or blend with the 2 tablespoons butter, 2 oz cream cheese, 1/4 cup parmesan and 1/2 teaspoon garlic powder until creamy.","Season with 1/2 teaspoon salt and 1/4 teaspoon pepper."]},
brocchickenbake:{list:["2 lb boneless chicken breasts, cut into bite size pieces","1 1/2 bags (12 oz each) frozen broccoli, about 4 cups","4 oz cream cheese (1/2 block), softened","1 cup shredded cheddar, divided","1 teaspoon garlic powder","1 teaspoon salt","1/2 teaspoon pepper"],
 steps:["Heat oven to 375°F.","Put the chicken and broccoli in a 9x13 baking dish and season with the 1 teaspoon salt and 1/2 teaspoon pepper.","Stir the 4 oz softened cream cheese with the 1 teaspoon garlic powder and 1/2 cup cheddar.","Spread the cream cheese mix over the chicken and broccoli.","Top with the last 1/2 cup cheddar.","Bake 25 to 30 minutes until the chicken is cooked through (165°F)."]},
koreanlettucecups:{list:["1 lb ground beef (or ground turkey)","1 head lettuce, leaves separated (about 12 leaves)","4 green onions, sliced","1/2 cucumber, thinly sliced","3 tablespoons soy sauce","1 teaspoon garlic powder","1/2 teaspoon ground ginger","1 tablespoon oil"],
 steps:["Heat the 1 tablespoon oil in a skillet over medium high heat.","Add the beef with the 1 teaspoon garlic powder and 1/2 teaspoon ginger. Cook 6 to 8 minutes, breaking it up, until browned. Drain the grease.","Stir in the 3 tablespoons soy sauce and cook 2 minutes more.","Slice the cucumber and green onions.","Spoon the beef into the lettuce leaves and top with cucumber and green onion."]},
sausagecabbage:{list:["1 package (13 oz) smoked sausage, sliced into coins","3/4 head cabbage, chopped (about 8 cups)","1/2 onion, chopped","2 tablespoons butter","1 1/2 teaspoons Cajun seasoning","1/4 cup water"],
 steps:["Brown the sausage coins in a large pot over medium heat for 5 minutes.","Add the onion and 2 tablespoons butter and cook 3 minutes.","Add the cabbage and 1/4 cup water. Cover and cook 15 minutes, stirring every few minutes, until the cabbage is tender.","Stir in the 1 1/2 teaspoons Cajun seasoning and taste. Add more if you like it spicier."]},
smotheredchopslc:{list:["4 pork chops (about 1 1/2 lb)","4 oz mushrooms, sliced","1/2 onion, sliced","1 cup chicken broth","1/2 cup heavy cream (or sour cream)","1 tablespoon butter","1/2 teaspoon chili powder","1/2 teaspoon cumin","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Season both sides of the chops with the chili powder, cumin, salt and pepper.","Melt the 1 tablespoon butter in a large skillet over medium high heat. Sear the chops 3 minutes per side, then move them to a plate.","Add the onion and mushrooms to the pan and cook 5 minutes until soft.","Pour in the 1 cup broth, scraping up the brown bits, and simmer 5 minutes.","Stir in the 1/2 cup cream.","Put the chops back in the pan and simmer 8 to 10 minutes, turning once, until cooked through (145°F) and the gravy thickens."]},
eggmuffins:{list:["10 large eggs","1/2 lb breakfast sausage (or diced ham)","1 1/2 cups baby spinach, chopped (or 1/2 cup thawed frozen spinach, squeezed dry)","1/2 cup shredded cheese","1/2 teaspoon salt","1/4 teaspoon pepper","Cooking spray"],
 steps:["Heat oven to 350°F. Spray a 12 cup muffin pan well.","Brown the 1/2 lb sausage in a skillet for 6 to 8 minutes and drain.","Divide the sausage, spinach and 1/2 cup cheese among the 12 cups.","Whisk the 10 eggs with the 1/2 teaspoon salt and 1/4 teaspoon pepper, then pour over the fillings, about 3/4 full.","Bake 20 to 22 minutes until the centers are set.","Cool 5 minutes before removing. Keep in the fridge up to 5 days and reheat 30 seconds in the microwave."]},
ketoscramble:{list:["8 large eggs","1/2 lb breakfast sausage","1 bell pepper, chopped (or 1 cup frozen peppers)","1/2 onion, chopped","1/2 cup shredded cheese","1/4 teaspoon salt"],
 steps:["Brown the 1/2 lb sausage with the pepper and onion in a large skillet over medium heat for 8 minutes.","Whisk the 8 eggs with the 1/4 teaspoon salt.","Turn the heat to low and pour in the eggs.","Stir gently until the eggs are just set, about 3 minutes.","Sprinkle with the 1/2 cup cheese and cover 1 minute to melt."]},
westernomelet:{list:["8 large eggs (2 per omelet)","6 oz ham steak, diced (about 1 cup)","1 bell pepper, diced","1/2 onion, diced","1/2 cup shredded cheese","1 tablespoon butter, plus a little for each omelet","Salt and pepper to taste"],
 steps:["Cook the ham, pepper and onion in the 1 tablespoon butter over medium heat for 5 minutes. Move to a bowl.","For each omelet, whisk 2 eggs with a pinch of salt and pepper.","Melt a little butter in a small nonstick pan over medium low heat and pour in the eggs.","When the edges set, about 2 minutes, spoon 1/4 of the filling and 2 tablespoons cheese on one half.","Fold the other half over and cook 1 minute more until set. Repeat for the rest."]},
tikkacauli:{list:["2 1/2 lb boneless chicken thighs (or breasts), cut into chunks","3/4 cup plain yogurt","2 bags (12 oz each) frozen riced cauliflower (or 1 1/2 cups rice)","1/2 onion, sliced","1 tablespoon curry powder","1 teaspoon garlic powder","1/2 teaspoon ground ginger","1 lemon, juiced","1 teaspoon salt","1 tablespoon oil"],
 steps:["Stir the 3/4 cup yogurt with the 1 tablespoon curry powder, 1 teaspoon garlic powder, 1/2 teaspoon ginger, lemon juice and 1 teaspoon salt.","Add the chicken and coat well. Let sit 15 minutes, or cover and chill overnight.","Heat the 1 tablespoon oil in a large skillet over medium high heat. Add the onion and chicken in one layer.","Cook 10 to 12 minutes, turning, until charred in spots and cooked through (165°F).","Microwave the cauliflower rice as the bag says.","Serve the chicken over the cauliflower rice."]},
saagchicken:{list:["2 1/2 lb boneless chicken thighs (or breasts), cut into chunks","1 bag (12 oz) frozen spinach","1 onion, chopped","1/2 cup heavy cream (or coconut milk)","2 teaspoons curry powder","1 teaspoon garlic powder","1/2 teaspoon ground ginger","1 teaspoon salt","2 tablespoons oil","1/2 cup water"],
 steps:["Heat 1 tablespoon oil in a large pot over medium high heat. Brown the chicken 5 minutes, then move to a plate.","Add the other 1 tablespoon oil and the onion. Cook 4 minutes until soft.","Stir in the 2 teaspoons curry powder, 1 teaspoon garlic powder and 1/2 teaspoon ginger for 30 seconds.","Add the spinach and 1/2 cup water. Cook 5 minutes. Blend it smooth if you like.","Stir in the 1/2 cup cream, the chicken and 1 teaspoon salt.","Simmer 10 minutes until the chicken is cooked through (165°F)."]},
tomkha:{list:["1 1/2 lb boneless chicken breast, thinly sliced","2 cans (13.5 oz each) coconut milk","2 cups chicken broth","4 oz mushrooms, sliced","2 limes, juiced","1/2 bunch cilantro, chopped","1 teaspoon ground ginger","2 tablespoons soy sauce"],
 steps:["In a pot, bring the 2 cups broth, both cans of coconut milk and the 1 teaspoon ginger to a simmer over medium heat.","Add the chicken and mushrooms.","Simmer 10 minutes until the chicken is cooked through. Do not let it boil hard.","Turn off the heat and stir in the lime juice and 2 tablespoons soy sauce.","Taste, then top bowls with cilantro."]},
thaipeanutwraps:{list:["1 1/2 lb boneless chicken breast (or two 12.5 oz cans chicken, drained)","3 tablespoons peanut butter","2 tablespoons soy sauce","2 limes, juiced","1/4 teaspoon ground ginger","2 to 3 tablespoons warm water","1 head lettuce, leaves separated","1/2 cucumber, cut in thin sticks","4 green onions, sliced"],
 steps:["Cook the chicken in a skillet over medium heat 6 to 7 minutes per side until done (165°F), then chop. Skip this if using canned.","Whisk the 3 tablespoons peanut butter, 2 tablespoons soy sauce, lime juice and 1/4 teaspoon ginger. Add warm water a tablespoon at a time until it is smooth and pourable.","Toss the chicken in the sauce.","Spoon into lettuce leaves and top with cucumber and green onion."]},
zoodlealfredo:{list:["4 zucchini","1 1/2 lb boneless chicken breast, cut into bite size pieces","1 jar (15 oz) alfredo sauce, about 1 1/3 cups (or 1 cup heavy cream plus 1/2 cup parmesan)","1/3 cup grated parmesan","1 teaspoon garlic powder","1 tablespoon butter","1/2 teaspoon salt"],
 steps:["Peel the zucchini into long thin ribbons with a vegetable peeler. Stop when you reach the seeds.","Melt the 1 tablespoon butter in a large skillet over medium high heat. Add the chicken, 1 teaspoon garlic powder and 1/2 teaspoon salt.","Cook 7 to 8 minutes until the chicken is cooked through.","Pour in the alfredo sauce and warm 2 minutes.","Add the zucchini and toss 2 minutes until just tender.","Top with the 1/3 cup parmesan."]},
stuffedpepperslc:{list:["4 bell peppers, halved and seeded","1 lb ground beef (or ground turkey)","1 packet (1 oz) taco seasoning","1 can (10 oz) tomatoes and green chiles","1 cup shredded cheese","1/2 cup sour cream"],
 steps:["Heat oven to 375°F.","Brown the beef in a skillet 6 to 8 minutes and drain.","Stir in the taco seasoning and the can of tomatoes. Simmer 5 minutes.","Set the pepper halves cut side up in a 9x13 dish and fill with the meat.","Top with the 1 cup cheese, cover with foil and bake 20 minutes. Uncover and bake 5 more.","Top with sour cream."]},
tacosalad:{list:["1 lb ground beef (or ground turkey)","1 packet (1 oz) taco seasoning","2/3 cup water","1 head lettuce, chopped","2 tomatoes, chopped","1 cup shredded cheese","1/2 cup salsa","1/2 cup sour cream","2 cups tortilla chips, crushed (or 1 avocado, sliced)"],
 steps:["Brown the beef in a skillet 6 to 8 minutes and drain.","Stir in the taco seasoning and 2/3 cup water. Simmer 5 minutes until thick.","Chop the lettuce and tomatoes.","Divide the lettuce among 4 bowls and top with meat, tomatoes, cheese, salsa and sour cream.","Add crushed chips or avocado on top."]},
carnitaslettuce:{list:["2 lb pork shoulder, cut into 3 inch chunks","3 limes, juiced","1/2 onion, diced","1/2 bunch cilantro, chopped","1 head lettuce, leaves separated (or 12 corn tortillas)","1/2 cup salsa","1 teaspoon chili powder","1 teaspoon cumin","1 teaspoon garlic powder","1 1/2 teaspoons salt","1 cup water"],
 steps:["Heat oven to 300°F.","Rub the pork with the 1 1/2 teaspoons salt, 1 teaspoon chili powder, 1 teaspoon cumin and 1 teaspoon garlic powder.","Put the pork in a pot with a lid. Add the lime juice and 1 cup water.","Cover and bake about 3 hours, until it falls apart with a fork.","Shred the pork. Crisp it in a hot skillet for 5 minutes with a few spoonfuls of the cooking juice.","Serve in lettuce leaves with onion, cilantro and salsa."]},
enchbake:{list:["2 cans (12.5 oz each) chicken, drained (or 3 cups cooked shredded chicken)","1 can (10 oz) red enchilada sauce","1/2 can tomatoes and green chiles","1 1/2 cups shredded cheese","1/2 cup sour cream","1/4 bunch cilantro, chopped"],
 steps:["Heat oven to 375°F.","In an 8x8 baking dish, stir together the chicken, the can of enchilada sauce and the tomatoes.","Cover with the 1 1/2 cups cheese.","Bake 20 minutes until bubbly.","Top with the sour cream and cilantro. Serve as is, or with chips or tortillas."]},
cajunfoil:{list:["1 lb frozen fish fillets, thawed","2 zucchini, sliced","1 bell pepper, sliced (or 1 cup frozen peppers)","1/2 onion, sliced","4 tablespoons butter (1 per packet)","1 lemon, sliced","2 teaspoons Cajun seasoning"],
 steps:["Heat oven to 400°F. Tear off 4 sheets of foil about 12 inches long.","Divide the zucchini, pepper and onion among the sheets, then lay a piece of fish on top.","Sprinkle each with 1/2 teaspoon Cajun seasoning and top with 1 tablespoon butter and a lemon slice.","Fold the foil over and crimp the edges to seal.","Bake on a sheet pan 18 to 20 minutes, until the fish flakes. Open carefully, the steam is hot."]},
lemonfishbeans:{list:["1 lb frozen fish fillets, thawed and patted dry","2 cans (14 oz each) green beans, drained","3 tablespoons butter, divided","1 1/2 lemons, juiced","1/2 teaspoon garlic powder","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Season the fish with the 1/2 teaspoon salt, 1/4 teaspoon pepper and 1/2 teaspoon garlic powder.","Melt 2 tablespoons butter in a large skillet over medium high heat.","Cook the fish 3 to 4 minutes per side until it flakes easily.","Squeeze the lemon juice over the fish and move it to a plate.","Add the last 1 tablespoon butter and the green beans to the pan. Cook 4 minutes until hot, then spoon the pan sauce over everything."]},
pizzachicken:{list:["2 lb boneless chicken breasts (about 3 large)","1 cup pasta sauce","1 cup shredded mozzarella or pizza cheese","2 oz sliced pepperoni (about 24 slices)","1 teaspoon Italian seasoning","1/2 teaspoon salt"],
 steps:["Heat oven to 400°F.","Slice each chicken breast in half the long way to make thin cutlets. Lay them in a baking dish.","Season with the 1/2 teaspoon salt and 1 teaspoon Italian seasoning.","Spread the 1 cup sauce over the chicken, then top with the cheese and pepperoni.","Bake 20 to 22 minutes until the chicken is cooked through (165°F)."]}
});
