yogurtpops:{list:["2 cups plain or vanilla yogurt","2 cups frozen berries","2 tablespoons honey","8 small paper cups and popsicle sticks"],
 steps:["Blend the 2 cups yogurt, 2 cups berries and 2 tablespoons honey until smooth.","Pour into 8 small cups or popsicle molds.","Freeze 1 hour, then push a stick into each.","Freeze 3 more hours. Run warm water over the outside to pop them out."]},
funnelcake:{list:["2 cups pancake mix","1 1/4 cups milk","1 large egg","3 cups oil for frying (about 1 inch deep)","3 tablespoons sugar, blended into powdered sugar"],
 steps:["Heat 1 inch of oil in a deep skillet to 375°F. Keep kids back from the hot oil.","Whisk the 2 cups pancake mix, 1 1/4 cups milk and 1 egg until smooth.","Pour the batter into a zip bag and snip off a small corner.","Squeeze about 1/2 cup batter into the oil in swirls.","Fry 1 minute per side until golden, then drain on paper towels.","Blend the 3 tablespoons sugar 30 seconds until powdery and dust over the funnel cakes. Makes about 6."]}
