Object.assign(FIX, {
handpies:{list:["2 refrigerated pie crusts (or 1 can of 8 biscuits)","3 apples, peeled and finely chopped (about 3 cups)","3 tablespoons sugar","2 tablespoons butter","1 teaspoon cinnamon","2 cups oil for frying (or skip and bake)"],
 steps:["Melt the 2 tablespoons butter in a skillet over medium heat. Add the apples, 3 tablespoons sugar and 1 teaspoon cinnamon.","Cook 8 to 10 minutes, stirring, until the apples are soft and syrupy. Cool 10 minutes.","Cut each crust into 4 circles about 5 inches wide, rerolling scraps. Or flatten each biscuit into a 5 inch circle.","Put 2 tablespoons filling on half of each circle, fold over and press the edges with a fork.","Fry in 1/2 inch of 350°F oil 2 minutes per side until golden. Or bake at 400°F for 15 minutes. Makes about 8."]},
sopapillas:{list:["8 flour tortillas","1/4 cup sugar","1 teaspoon cinnamon","1/4 cup honey","2 cups oil for frying"],
 steps:["Cut each tortilla into 4 wedges.","Heat 1/2 inch of oil in a skillet to 350°F.","Fry the wedges a few at a time, about 30 seconds per side, until puffed and golden. Drain on paper towels.","Mix the 1/4 cup sugar and 1 teaspoon cinnamon and toss the warm wedges in it.","Drizzle with honey."]},
coconutrice:{list:["1 cup rice","1 1/2 cups water","1 can (13.5 oz) coconut milk","3 tablespoons sugar","1/4 teaspoon salt","2 bananas, sliced"],
 steps:["Bring the 1 cup rice and 1 1/2 cups water to a boil. Cover, turn to low and cook 18 minutes.","Warm the coconut milk with the 3 tablespoons sugar and 1/4 teaspoon salt until the sugar dissolves. Do not boil.","Stir 3/4 of the coconut sauce into the hot rice. Cover and let it soak 15 minutes.","Serve the rice with sliced bananas and spoon the rest of the sauce over the top."]},
gulabjamun:{list:["DOUGH: 1 cup dry powdered milk","1/4 cup flour","1/4 teaspoon baking powder","1 tablespoon butter, melted","4 to 5 tablespoons milk","2 cups oil for frying","SYRUP: 1 1/2 cups sugar","1 1/2 cups water","1/2 teaspoon cinnamon"],
 steps:["Make the syrup first: simmer the 1 1/2 cups sugar, 1 1/2 cups water and 1/2 teaspoon cinnamon 5 minutes. Keep warm.","Mix the 1 cup powdered milk, 1/4 cup flour and baking powder. Stir in the melted butter.","Add milk a tablespoon at a time until it forms a soft, smooth dough. Rest 5 minutes.","Roll into 16 smooth balls with no cracks.","Heat 2 inches of oil on low, about 300°F. Fry the balls, turning, 6 to 8 minutes until deep golden brown.","Drop the hot balls into the warm syrup and soak at least 20 minutes."]},
dorayaki:{list:["1 1/2 cups pancake mix","2 large eggs","1 tablespoon honey","2/3 cup milk","1/2 cup grape jelly (or peanut butter)","Cooking spray"],
 steps:["Whisk the 1 1/2 cups pancake mix, 2 eggs, 1 tablespoon honey and 2/3 cup milk until smooth. Rest 5 minutes.","Heat a lightly sprayed nonstick pan over medium low heat.","Pour 3 tablespoons batter per pancake to make 3 inch rounds. Cook until bubbles form, about 2 minutes, then flip for 1 minute.","Cool the pancakes on a towel.","Spread 1 tablespoon jelly on one pancake and top with a second. Makes about 8."]},
cannolidip:{list:["1 block (8 oz) cream cheese, softened","1/2 cup heavy cream","1/2 cup sugar","1 teaspoon vanilla extract","1 teaspoon cocoa powder for dusting","1 sleeve graham crackers (about 9 sheets), broken into pieces"],
 steps:["Beat the 8 oz cream cheese until smooth.","Beat in the 1/2 cup sugar and 1 teaspoon vanilla.","Slowly pour in the 1/2 cup cream while beating, and beat 2 minutes until fluffy.","Spoon into a bowl and dust with the cocoa.","Serve with graham crackers."]},
eggtarts:{list:["2 refrigerated pie crusts","3 large eggs","3/4 cup milk","1/3 cup sugar","1/2 teaspoon vanilla extract"],
 steps:["Heat oven to 400°F.","Cut the crusts into 12 circles with a wide glass, rerolling scraps. Press each into a muffin cup.","Warm the 3/4 cup milk with the 1/3 cup sugar just until it dissolves, then cool 5 minutes.","Whisk in the 3 eggs and 1/2 teaspoon vanilla. Strain through a sieve for a smooth custard.","Fill each shell about 3/4 full.","Bake 18 to 20 minutes until the custard is just set and only jiggles a little. Cool 10 minutes."]},
crepes:{list:["1 cup flour","2 large eggs","1 1/2 cups milk","2 tablespoons butter, melted, plus more for the pan","1 tablespoon sugar","1/4 teaspoon salt","1/2 cup jam (or 2 bananas, sliced)"],
 steps:["Blend the 1 cup flour, 2 eggs, 1 1/2 cups milk, 2 tablespoons melted butter, 1 tablespoon sugar and salt until smooth. Rest 10 minutes.","Heat an 8 inch nonstick pan over medium heat and brush with butter.","Pour in 1/4 cup batter and swirl to coat the pan thinly.","Cook 1 minute until the edges lift, flip and cook 30 seconds.","Fill each crepe with a spoonful of jam or bananas and roll up. Makes about 10."]},
pbpie:{list:["1 1/2 sleeves graham crackers, crushed (about 1 1/2 cups crumbs)","1/4 cup (4 tablespoons) butter, melted","1 block (8 oz) cream cheese, softened","3/4 cup peanut butter","1/2 cup sugar","1 cup heavy cream, cold"],
 steps:["Stir the graham crumbs with the melted butter and press firmly into a 9 inch pie pan.","Beat the 8 oz cream cheese, 3/4 cup peanut butter and 1/2 cup sugar until smooth.","In another bowl, whip the 1 cup cold cream to stiff peaks, about 3 minutes with a mixer.","Fold the whipped cream into the peanut butter mix in 2 parts.","Spread in the crust and chill at least 4 hours."]},
fruitpizza:{list:["CRUST: 1/2 cup (1 stick) butter, softened","3/4 cup sugar","1 large egg","1 teaspoon vanilla extract","1 1/2 cups flour","1/2 teaspoon baking powder","TOPPING: 1 block (8 oz) cream cheese, softened","1/4 cup sugar","1/2 teaspoon vanilla extract","1 1/2 cups frozen berries, thawed and drained (or canned fruit)","1 banana, sliced"],
 steps:["Heat oven to 350°F.","Beat the 1 stick butter and 3/4 cup sugar, then the egg and 1 teaspoon vanilla.","Stir in the 1 1/2 cups flour and 1/2 teaspoon baking powder.","Press into a 12 inch circle on a pizza pan or baking sheet.","Bake 12 to 14 minutes until lightly golden. Cool completely.","Beat the 8 oz cream cheese with the 1/4 cup sugar and 1/2 teaspoon vanilla and spread over the crust.","Top with the fruit and cut into wedges."]},
puddingsandwiches:{list:["1 box (3.4 oz) vanilla instant pudding mix","1 1/2 cups cold milk","1 1/2 sleeves graham crackers (about 12 sheets), broken into 24 squares"],
 steps:["Whisk the pudding mix with the 1 1/2 cups cold milk for 2 minutes. Chill 5 minutes to thicken.","Spread about 2 tablespoons pudding on a graham square and top with another.","Wrap each sandwich in plastic wrap.","Freeze at least 3 hours. Makes 12."]},
cupcakes:{list:["CUPCAKES: 1/2 cup (1 stick) butter, softened","1 cup sugar","2 large eggs","2 teaspoons vanilla extract","1 1/2 cups flour","2 teaspoons baking powder","1/4 teaspoon salt","1/2 cup milk","FROSTING: 1/2 cup (1 stick) butter, softened","1 1/2 cups sugar blended into powdered sugar (or 2 cups powdered sugar)","1 to 2 tablespoons milk","1 teaspoon vanilla extract"],
 steps:["Heat oven to 350°F. Line a 12 cup muffin pan.","Beat the 1 stick butter and 1 cup sugar until fluffy, then beat in the 2 eggs and 2 teaspoons vanilla.","Mix the 1 1/2 cups flour, 2 teaspoons baking powder and 1/4 teaspoon salt.","Stir half the flour mix into the batter, then the 1/2 cup milk, then the rest of the flour.","Fill the cups 2/3 full and bake 18 to 20 minutes until a toothpick comes out clean. Cool completely.","For the frosting, blend the 1 1/2 cups sugar 30 seconds until powdery. Beat with the 1 stick butter, 1 teaspoon vanilla and milk until fluffy, then frost."]},
oatmealpies:{list:["COOKIES: 1/2 cup (1 stick) butter, softened","3/4 cup packed brown sugar","1 large egg","1 teaspoon vanilla extract","1 cup flour","1 cup quick or old fashioned oats","1/2 teaspoon baking powder","1/2 teaspoon cinnamon","1/4 teaspoon salt","FILLING: 1/2 cup (1 stick) butter, softened","1 1/2 cups sugar blended into powdered sugar","1 teaspoon vanilla extract","1 tablespoon milk"],
 steps:["Heat oven to 350°F. Line 2 baking sheets.","Beat the 1 stick butter and 3/4 cup brown sugar, then beat in the egg and 1 teaspoon vanilla.","Stir in the 1 cup flour, 1 cup oats, baking powder, cinnamon and salt.","Drop 24 tablespoon scoops 2 inches apart. Bake 9 minutes until just set. Cool completely.","For the filling, blend the 1 1/2 cups sugar until powdery, then beat with the 1 stick butter, 1 teaspoon vanilla and 1 tablespoon milk until fluffy.","Spread filling on the flat side of half the cookies and top with the rest. Makes 12."]},
bakedapples:{list:["4 apples","1/3 cup old fashioned oats","1/4 cup packed brown sugar","2 tablespoons butter, softened","1 teaspoon cinnamon","1/2 cup water"],
 steps:["Heat oven to 350°F.","Core the apples with a spoon or small knife, leaving the bottom 1/2 inch so the filling stays in.","Mix the 1/3 cup oats, 1/4 cup brown sugar, 2 tablespoons butter and 1 teaspoon cinnamon.","Pack the filling into the apples and set them in a baking dish.","Pour the 1/2 cup water into the dish.","Bake 35 to 40 minutes until the apples are tender."]},
horchata:{list:["1 cup long grain rice","1 cinnamon stick or 1 teaspoon ground cinnamon","3 cups water for soaking","2 cups milk","1/2 cup sugar","1 teaspoon vanilla extract","Ice"],
 steps:["Soak the 1 cup rice and cinnamon in the 3 cups water overnight, or at least 4 hours.","Blend the rice, cinnamon and soaking water 2 minutes until very smooth.","Strain through a fine sieve or a clean towel, pressing out all the liquid.","Stir in the 2 cups milk, 1/2 cup sugar and 1 teaspoon vanilla until the sugar dissolves.","Chill and serve over ice. Stir before pouring."]},
kettlecorn:{list:["1/2 cup popcorn kernels","3 tablespoons oil","1/4 cup sugar","1/2 teaspoon salt"],
 steps:["Heat the 3 tablespoons oil with 3 kernels in a large pot with a lid over medium high heat.","When those kernels pop, add the rest of the 1/2 cup kernels and sprinkle the 1/4 cup sugar over them.","Cover and shake the pot constantly so the sugar does not burn.","When popping slows to 2 seconds between pops, pour it onto a baking sheet right away.","Sprinkle with the 1/2 teaspoon salt and break up clumps as it cools."]},
fruitleather:{list:["2 cups frozen berries, thawed","1 1/2 cups applesauce","2 tablespoons honey"],
 steps:["Heat oven to 170°F, or the lowest setting. Line a rimmed baking sheet with parchment.","Blend the 2 cups berries, 1 1/2 cups applesauce and 2 tablespoons honey until smooth.","Spread about 1/8 inch thick in an even layer.","Bake about 4 hours until the center is no longer sticky.","Cool, then cut into strips with the parchment and roll up."]},
applechips:{list:["1 lb apples (about 3), thinly sliced","1 teaspoon cinnamon"],
 steps:["Heat oven to 225°F. Line 2 baking sheets with parchment.","Slice the apples as thin as you can, about 1/8 inch. Cut out the seeds.","Lay the slices in one layer and sprinkle with the 1 teaspoon cinnamon.","Bake 1 hour, flip, and bake 45 to 60 minutes more until dry.","Turn off the oven and let them cool inside. They crisp as they cool."]},
cerealbars:{list:["4 cups cereal (rice or corn cereal works best)","3/4 cup peanut butter (or sunflower butter)","1/2 cup honey","Cooking spray"],
 steps:["Spray an 8x8 pan, or line it with parchment.","Warm the 3/4 cup peanut butter and 1/2 cup honey in a pot over low heat, or microwave 1 minute, stirring until smooth.","Stir in the 4 cups cereal until coated.","Press firmly into the pan.","Chill 1 hour and cut into 16 bars."]},
cinnchips:{list:["6 flour tortillas","2 tablespoons butter, melted","2 tablespoons sugar","1 teaspoon cinnamon"],
 steps:["Heat oven to 375°F.","Brush both sides of each tortilla with the melted butter.","Mix the 2 tablespoons sugar and 1 teaspoon cinnamon and sprinkle over the tortillas.","Cut each into 8 wedges and spread on baking sheets in one layer.","Bake 8 to 10 minutes until crisp. They harden more as they cool."]},
snackmix:{list:["4 cups cereal","1 sleeve saltine crackers, broken into pieces","1/4 cup (4 tablespoons) butter, melted","1 tablespoon ranch dressing (or 1 teaspoon garlic powder plus 1/2 teaspoon onion powder)","1/4 teaspoon salt"],
 steps:["Heat oven to 250°F.","Stir the melted butter with the ranch and salt.","Toss with the cereal and crackers until coated.","Spread on a baking sheet.","Bake 15 minutes, stir, then bake 10 minutes more. Cool and store in a sealed bag."]},
homeapplesauce:{list:["6 apples (about 1 1/2 lb), peeled and chopped","1/2 cup water","1 tablespoon lemon juice","1/2 teaspoon cinnamon"],
 steps:["Put the apples, 1/2 cup water and 1 tablespoon lemon juice in a pot.","Cover and simmer over medium low heat 20 minutes, stirring now and then, until very soft.","Mash with a potato masher for chunky, or blend for smooth.","Stir in the 1/2 teaspoon cinnamon. Serve warm or cold."]},
pizzarolls:{list:["24 dumpling wrappers (or 4 flour tortillas cut into squares)","2/3 cup pasta sauce","3/4 cup shredded mozzarella","2 oz pepperoni, chopped","1 tablespoon oil","Small bowl of water"],
 steps:["Heat oven to 425°F. Line a baking sheet with parchment.","Put 1 teaspoon sauce, a pinch of cheese and a few pieces of pepperoni in the center of each wrapper.","Wet the edges with water, fold in half and press tight to seal.","Set on the sheet and brush with the 1 tablespoon oil.","Bake 10 to 12 minutes until golden and crisp. Cool 3 minutes, the filling is very hot."]},
pigsblanket:{list:["1 package (8 count) hot dogs, each cut in half","1 can (8 count) refrigerated biscuits","Ketchup and mustard for dipping"],
 steps:["Heat oven to 375°F.","Cut each biscuit in half and stretch each half into a strip about 5 inches long.","Wrap a strip around each hot dog half and set seam side down on a baking sheet.","Bake 12 to 15 minutes until golden.","Serve with ketchup and mustard. Makes 16."]},
pitapizzas:{list:["6 pitas (or flour tortillas)","1 cup pasta sauce","1 cup shredded mozzarella","2 oz sliced pepperoni (or 1 bell pepper, sliced)","1 teaspoon Italian seasoning"],
 steps:["Heat oven to 425°F.","Set the pitas on a baking sheet and spread each with about 2 1/2 tablespoons sauce.","Top each with cheese and pepperoni or peppers, and sprinkle with Italian seasoning.","Bake 8 to 10 minutes until the cheese bubbles."]},
crackertenders:{list:["2 lb boneless chicken breasts, cut into strips","1 sleeve saltine crackers, crushed (about 1 1/4 cups crumbs)","2 large eggs","2 tablespoons butter, melted","1/2 teaspoon garlic powder","1/2 cup ranch dressing or ketchup for dipping"],
 steps:["Heat oven to 425°F. Line a baking sheet with foil and grease it.","Beat the 2 eggs in a shallow bowl. Mix the cracker crumbs with the 1/2 teaspoon garlic powder in another.","Dip each chicken strip in egg, then press into the crumbs.","Lay on the sheet and drizzle with the melted butter.","Bake 18 to 20 minutes, flipping halfway, until cooked through (165°F).","Serve with ranch or ketchup."]},
fishsticks:{list:["1 lb frozen fish fillets, thawed and patted dry","1/4 cup flour","2 large eggs","1 1/4 cups breadcrumbs (or crushed crackers)","2 tablespoons oil","1/2 teaspoon salt","1/4 cup mayo for dipping"],
 steps:["Heat oven to 425°F. Line a baking sheet with foil and grease it.","Cut the fish into strips about 1 inch wide and sprinkle with the 1/2 teaspoon salt.","Set out 3 bowls: the 1/4 cup flour, the 2 beaten eggs, and the breadcrumbs.","Dip each strip in flour, then egg, then crumbs, and lay on the sheet.","Brush or drizzle with the 2 tablespoons oil.","Bake 12 to 15 minutes, flipping once, until golden and the fish flakes. Serve with mayo."]},
meatloafmuffins:{list:["1 lb ground beef (or ground turkey)","1/2 cup oats","1 large egg","1/4 onion, grated","1/4 cup ketchup, plus 1/3 cup for the glaze","2 tablespoons brown sugar","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Heat oven to 375°F. Grease a 12 cup muffin pan.","Mix the beef, 1/2 cup oats, 1 egg, onion, 1/4 cup ketchup, salt and pepper with your hands.","Press into the 12 cups.","Stir the 1/3 cup ketchup with the 2 tablespoons brown sugar and spoon over the tops.","Bake 20 to 22 minutes until cooked through (160°F)."]}
});
Object.assign(FIX, {
cheeseburgersliders:{list:["1 lb ground beef","8 hamburger buns (or slider rolls)","1 cup shredded cheddar","1/4 onion, finely diced","2 tablespoons butter, melted","1/2 teaspoon salt","1/4 teaspoon pepper","Ketchup and mustard"],
 steps:["Heat oven to 350°F.","Brown the beef with the onion, salt and pepper in a skillet 6 to 8 minutes. Drain the grease.","Set the bottom buns in a 9x13 pan, touching.","Spread the beef over them, add a little ketchup and mustard, and top with the 1 cup cheese.","Put the top buns on and brush with the melted butter.","Bake 12 to 15 minutes until the cheese melts and the tops are toasty. Pull apart to serve."]},
hamsliders:{list:["8 hamburger buns (or slider rolls)","1/2 lb ham steak, thinly sliced (or deli ham)","1 cup shredded Swiss or cheddar","1/4 cup (4 tablespoons) butter, melted","1 tablespoon mustard"],
 steps:["Heat oven to 350°F.","Set the bottom buns in a 9x13 pan.","Layer the ham and 1 cup cheese on top, then add the top buns.","Stir the 1 tablespoon mustard into the melted butter and brush over the tops.","Cover with foil and bake 15 minutes. Uncover and bake 5 minutes more to toast the tops."]},
maccups:{list:["1/2 lb (half a box) elbow macaroni","1 1/2 cups shredded cheddar, divided","1 large egg","1/2 cup milk","2 tablespoons butter","1/4 teaspoon salt","Cooking spray"],
 steps:["Heat oven to 375°F. Spray a 12 cup muffin pan well.","Boil the macaroni in salted water 6 minutes, a little firm. Drain.","Stir in the 2 tablespoons butter and 1 1/4 cups cheese until melted.","Whisk the egg with the 1/2 cup milk and salt, and stir into the pasta.","Fill the muffin cups and top with the last 1/4 cup cheese.","Bake 15 minutes. Cool 10 minutes so they hold together."]},
tacocups:{list:["8 flour tortillas","1 lb ground beef (or ground turkey)","1 packet (1 oz) taco seasoning","2/3 cup water","1 cup shredded cheese","1/3 cup salsa","1/3 cup sour cream","Cooking spray"],
 steps:["Heat oven to 375°F. Spray a 12 cup muffin pan.","Brown the beef 6 to 8 minutes and drain. Stir in the taco seasoning and 2/3 cup water and simmer 5 minutes.","Cut 24 circles from the tortillas with a wide glass, and press 2 into each muffin cup.","Fill each with meat and top with cheese.","Bake 10 to 12 minutes until the edges are crisp.","Top with salsa and sour cream. Makes 12."]},
spaghettipie:{list:["1/2 lb spaghetti","2 large eggs","1/3 cup grated parmesan","1 lb ground beef (or Italian sausage)","1 3/4 cups pasta sauce","1 cup shredded mozzarella","2 tablespoons butter"],
 steps:["Heat oven to 350°F. Grease a 9 inch pie pan.","Boil the spaghetti until tender and drain. Toss with the 2 tablespoons butter.","Beat the 2 eggs with the 1/3 cup parmesan and toss with the warm pasta.","Press the pasta into the pie pan to make a crust.","Brown the beef 6 to 8 minutes, drain, and stir in the 1 3/4 cups sauce. Spread over the crust.","Cover with the 1 cup cheese and bake 25 minutes. Rest 5 minutes before slicing."]},
breakfastpizza:{list:["1 can (8 count) refrigerated biscuits","6 large eggs","1/2 lb breakfast sausage (or 6 slices bacon)","1 cup shredded cheese","1 tablespoon milk","Pinch of salt and pepper"],
 steps:["Heat oven to 375°F. Grease a baking sheet or 12 inch pizza pan.","Press the biscuits together into one flat crust about 1/4 inch thick.","Bake the crust 8 minutes.","Meanwhile, brown the sausage 6 to 8 minutes and drain.","Whisk the 6 eggs with the milk, salt and pepper and scramble softly in the same pan, about 2 minutes. Keep them a little wet.","Top the crust with eggs, sausage and the 1 cup cheese. Bake 10 minutes more."]},
pancakemuffins:{list:["2 cups pancake mix","1 1/4 cups milk","1 large egg","3/4 cup frozen berries (or 1 banana, sliced)","1/3 cup pancake syrup for dipping","Cooking spray"],
 steps:["Heat oven to 350°F. Spray a 12 cup muffin pan.","Stir the 2 cups pancake mix, 1 1/4 cups milk and 1 egg until just mixed. A few lumps are fine.","Fill the cups 2/3 full.","Drop a few berries or banana slices into each.","Bake 14 to 16 minutes until springy.","Serve with syrup for dipping."]},
bananaoatmuffins:{list:["2 cups old fashioned oats","2 ripe bananas","2 large eggs","1/4 cup honey","1/2 cup milk","1 1/2 teaspoons baking powder","1 teaspoon cinnamon","Pinch of salt","Cooking spray"],
 steps:["Heat oven to 350°F. Spray a 12 cup muffin pan.","Blend the 2 cups oats first until they look like flour.","Add the bananas, 2 eggs, 1/4 cup honey, 1/2 cup milk, baking powder, cinnamon and salt. Blend until smooth.","Pour into the cups, about 3/4 full.","Bake 18 to 20 minutes until a toothpick comes out clean."]},
pizzaquesadilla:{list:["8 flour tortillas","2 cups shredded mozzarella","2 oz sliced pepperoni (about 24 slices)","1/2 cup pasta sauce, warmed"],
 steps:["Heat a dry skillet over medium heat.","Lay a tortilla in the pan. Sprinkle 1/4 cup cheese and 3 pepperoni slices over half.","Fold it over and cook 2 minutes per side until golden and melted.","Repeat with the rest.","Cut into wedges and dip in the warm sauce."]},
taquitos:{list:["15 corn tortillas (or 10 flour tortillas)","2 cans (12.5 oz each) chicken, drained and shredded","4 oz cream cheese (1/2 block), softened","3/4 cup shredded cheese","1/3 cup salsa","2 tablespoons oil"],
 steps:["Heat oven to 425°F. Line a baking sheet with foil and brush it with oil.","Mix the chicken, 4 oz cream cheese, 3/4 cup cheese and 1/3 cup salsa.","Wrap the tortillas in a damp paper towel and microwave 45 seconds so they roll without cracking.","Spread 2 tablespoons filling along one edge of each tortilla and roll tight.","Set seam side down on the sheet and brush with the oil.","Bake 15 minutes until crisp and golden."]},
butternoodles:{list:["1 lb spaghetti or egg noodles","1/2 cup (1 stick) butter","3/4 cup grated parmesan","1/2 teaspoon garlic powder","1/2 teaspoon salt","2 cups frozen broccoli, steamed (optional)"],
 steps:["Boil the pasta in salted water until tender. Scoop out 1 cup of the pasta water, then drain.","Put the pasta back in the pot over low heat with the 1 stick butter.","Toss in the 3/4 cup parmesan, garlic powder and 1/4 cup pasta water. Add more water if it looks dry.","Season with the salt and stir in the broccoli if using."]},
brocrice:{list:["2 cups rice","4 cups chicken broth (or water with 4 teaspoons bouillon)","1 bag (12 oz) frozen broccoli","1 cup shredded cheddar","1/2 cup milk","2 tablespoons butter","1 can (12.5 oz) chicken, drained"],
 steps:["Bring the 4 cups broth to a boil. Add the 2 cups rice, cover, turn to low and cook 18 minutes.","Microwave the broccoli as the bag says and chop it small.","Stir the 1 cup cheese, 1/2 cup milk and 2 tablespoons butter into the hot rice until creamy.","Fold in the broccoli and chicken and heat through."]},
teriyakimeatballs:{list:["1/2 bag (about 12 oz) frozen meatballs (about 24)","1/3 cup soy sauce","1/3 cup packed brown sugar","1/3 cup water","1/2 teaspoon ground ginger","1/2 teaspoon garlic powder","1 1/2 cups rice","4 green onions, sliced"],
 steps:["Cook the 1 1/2 cups rice: boil with 3 cups water, cover, turn to low and cook 18 minutes.","Bake the meatballs as the bag says, usually 15 to 20 minutes at 375°F.","In a skillet, simmer the 1/3 cup soy sauce, 1/3 cup brown sugar, 1/3 cup water, ginger and garlic 5 minutes until syrupy.","Toss the meatballs in the glaze.","Serve over rice with green onion."]},
chickenpotpie:{list:["2 cans (12.5 oz each) chicken, drained","1 bag (12 oz) frozen mixed vegetables","1 can (10 oz) cream of chicken soup","1/2 cup milk","1/2 teaspoon poultry seasoning","1/4 teaspoon pepper","1 can (8 count) refrigerated biscuits"],
 steps:["Heat oven to 375°F.","In an 8x8 or 9 inch baking dish, stir the chicken, vegetables, soup, 1/2 cup milk, poultry seasoning and pepper.","Bake 10 minutes to warm the filling.","Lay the 8 biscuits on top.","Bake 15 to 18 minutes more until the biscuits are golden and the filling bubbles."]},
chickenalfredobake:{list:["1 lb spaghetti or elbow pasta","1 jar (15 oz) alfredo sauce","2 cans (12.5 oz each) chicken, drained (or 3 cups cooked chicken)","2 cups frozen broccoli, thawed","1 cup shredded mozzarella"],
 steps:["Heat oven to 375°F.","Boil the pasta 2 minutes less than the box says and drain.","Toss the pasta with the alfredo sauce, chicken and broccoli in a 9x13 dish.","Top with the 1 cup cheese.","Bake 20 minutes until bubbly."]},
hotdogbites:{list:["1 package (8 count) hot dogs, each cut into 4 pieces","1/2 cup cornmeal","1/2 cup flour","1 tablespoon sugar","1 1/2 teaspoons baking powder","1/4 teaspoon salt","1 large egg","1/2 cup milk","2 cups oil for frying","Ketchup and mustard"],
 steps:["Heat 2 inches of oil in a deep pot to 350°F. Keep kids back from the hot oil.","Whisk the 1/2 cup cornmeal, 1/2 cup flour, 1 tablespoon sugar, baking powder and salt. Whisk in the egg and 1/2 cup milk.","Pat the hot dog pieces dry with a paper towel so the batter sticks.","Dip a few at a time in the batter, letting the extra drip off.","Fry 2 to 3 minutes, turning, until golden. Drain on paper towels.","Serve with ketchup and mustard. Makes 32."]},
bananasmoothiebowl:{list:["2 bananas","2 cups milk","3/4 cup yogurt","3 tablespoons peanut butter (or sunflower butter)","2 tablespoons oats","1 tablespoon honey","1 cup ice"],
 steps:["Add the 2 bananas, 2 cups milk, 3/4 cup yogurt and 3 tablespoons peanut butter to a blender.","Add the 2 tablespoons oats, 1 tablespoon honey and 1 cup ice.","Blend 1 minute until smooth.","Pour into 4 glasses."]},
zucchinibread:{list:["2 cups grated zucchini (about 2 small), squeezed dry","2 large eggs","1 1/2 cups sugar","1/2 cup oil","1 teaspoon vanilla extract","2 cups flour","2 teaspoons baking powder","2 teaspoons cinnamon","1/2 teaspoon salt"],
 steps:["Heat oven to 350°F. Grease a 9x5 loaf pan.","Grate the zucchini, then squeeze it in a towel to get out as much water as you can.","Whisk the 2 eggs, 1 1/2 cups sugar, 1/2 cup oil and 1 teaspoon vanilla. Stir in the zucchini.","Stir in the 2 cups flour, 2 teaspoons baking powder, 2 teaspoons cinnamon and 1/2 teaspoon salt until just mixed.","Pour into the pan and bake 55 to 60 minutes until a toothpick comes out clean.","Cool 10 minutes in the pan, then turn out."]},
pumpkinmuffins:{list:["1 can (15 oz) pumpkin","1 cup sugar, plus 1 tablespoon for the top","2 large eggs","1/3 cup oil","1 3/4 cups flour","2 teaspoons baking powder","2 teaspoons cinnamon, plus 1/2 teaspoon for the top","1/2 teaspoon salt"],
 steps:["Heat oven to 375°F. Line a 12 cup muffin pan.","Whisk the pumpkin, 1 cup sugar, 2 eggs and 1/3 cup oil.","Stir in the 1 3/4 cups flour, 2 teaspoons baking powder, 2 teaspoons cinnamon and 1/2 teaspoon salt until just mixed.","Fill the cups almost full.","Mix the 1 tablespoon sugar with the 1/2 teaspoon cinnamon and sprinkle on top.","Bake 20 to 22 minutes until a toothpick comes out clean."]},
bgravy:{list:["1 can (8 count) refrigerated biscuits","1 lb breakfast sausage","1/4 cup flour","2 1/2 cups milk (or 1 can evaporated milk plus 1 cup water)","1/2 teaspoon pepper","1/4 teaspoon salt"],
 steps:["Bake the biscuits as the can says.","Brown the 1 lb sausage in a large skillet over medium heat 8 minutes, breaking it up. Do not drain.","Sprinkle the 1/4 cup flour over the sausage and stir 1 minute.","Slowly pour in the 2 1/2 cups milk, stirring the whole time.","Simmer 3 to 5 minutes, stirring, until thick. Season with the pepper and salt.","Split the biscuits and spoon the gravy over them."]},
oatspb:{list:["2 cups old fashioned oats","2 cups milk (or soy milk)","1/4 cup peanut butter (or sunflower butter)","2 bananas, sliced"],
 steps:["In 4 jars or bowls, stir 1/2 cup oats, 1/2 cup milk and 1 tablespoon peanut butter.","Cover and refrigerate overnight, or at least 4 hours.","Top each with half a sliced banana in the morning."]},
oatspbj:{list:["2 cups old fashioned oats","2 cups milk (or soy milk)","1/4 cup peanut butter (or sunflower butter)","1/4 cup grape jelly or any jam"],
 steps:["In 4 jars or bowls, stir 1/2 cup oats, 1/2 cup milk and 1 tablespoon peanut butter.","Swirl 1 tablespoon jelly on top of each.","Cover and refrigerate overnight, or at least 4 hours."]},
oatsapple:{list:["2 cups old fashioned oats","2 cups milk (or soy milk)","1 cup applesauce (or 1 apple, diced)","1 teaspoon cinnamon","4 teaspoons sugar"],
 steps:["In 4 jars or bowls, stir 1/2 cup oats, 1/2 cup milk, 1/4 cup applesauce, 1/4 teaspoon cinnamon and 1 teaspoon sugar.","Cover and refrigerate overnight, or at least 4 hours."]},
oatschoc:{list:["2 cups old fashioned oats","2 cups milk (or soy milk)","4 teaspoons cocoa powder","1/4 cup peanut butter (or sunflower butter)","4 teaspoons sugar"],
 steps:["In 4 jars or bowls, stir 1/2 cup oats, 1/2 cup milk, 1 teaspoon cocoa, 1 tablespoon peanut butter and 1 teaspoon sugar.","Cover and refrigerate overnight, or at least 4 hours. Stir before eating."]},
oatsberry:{list:["2 cups old fashioned oats","2 cups yogurt (or milk)","1 1/2 cups frozen berries (or canned fruit)","4 teaspoons sugar"],
 steps:["In 4 jars or bowls, stir 1/2 cup oats, 1/2 cup yogurt and 1 teaspoon sugar.","Top each with about 1/3 cup frozen berries.","Cover and refrigerate overnight. The berries thaw into a sauce."]}
});
Object.assign(FIX, {
s_tortillas:{list:["3 cups flour, plus a little for rolling","1 teaspoon baking powder","1 teaspoon salt","1/3 cup oil","About 1 cup warm water"],
 steps:["Mix the 3 cups flour, 1 teaspoon baking powder and 1 teaspoon salt in a bowl.","Stir in the 1/3 cup oil, then add the warm water a little at a time until a soft dough forms. You may not need all of it.","Knead 2 minutes until smooth.","Split into 10 balls, cover with a towel and rest 10 minutes.","Roll each ball into a thin 8 inch circle on a floured counter.","Cook in a dry skillet over medium high heat 30 to 45 seconds per side, until bubbly with brown spots. Stack in a towel to stay soft. Makes 10."]},
s_pizza:{list:["1 packet (2 1/4 teaspoons) yeast","1 teaspoon sugar","1 cup warm water (about 110°F, warm like bath water)","2 1/2 cups flour","2 tablespoons oil, plus more for the pan","1 teaspoon salt"],
 steps:["Stir the yeast and 1 teaspoon sugar into the 1 cup warm water. Wait 5 minutes until foamy.","Add the 2 1/2 cups flour, 2 tablespoons oil and 1 teaspoon salt and stir into a shaggy dough.","Knead 5 minutes on a floured counter until smooth and stretchy.","Put in an oiled bowl, cover and let rise 1 hour until doubled.","Press into an oiled pan, add toppings and bake at 450°F for 12 to 15 minutes. Makes one 14 inch pizza."]},
s_bread:{list:["1 packet (2 1/4 teaspoons) yeast","2 tablespoons sugar","1 1/4 cups warm water (about 110°F)","3 1/2 cups flour","2 tablespoons oil","1 1/2 teaspoons salt"],
 steps:["Stir the yeast and 2 tablespoons sugar into the 1 1/4 cups warm water. Wait 5 minutes until foamy.","Add the 3 1/2 cups flour, 2 tablespoons oil and 1 1/2 teaspoons salt. Stir into a dough.","Knead 8 minutes until smooth and springy.","Cover and let rise in an oiled bowl 1 hour until doubled.","Press flat, roll up tight into a log and set in a greased 9x5 loaf pan. Cover and rise 45 minutes.","Bake at 375°F for 30 to 35 minutes until golden and hollow sounding when tapped. Cool before slicing."]},
s_biscuits:{list:["2 cups flour","1 tablespoon baking powder","1 teaspoon salt","6 tablespoons cold butter (or 1/3 cup oil)","3/4 cup cold milk"],
 steps:["Heat oven to 450°F.","Mix the 2 cups flour, 1 tablespoon baking powder and 1 teaspoon salt.","Cut the 6 tablespoons cold butter into small pieces and rub it in with your fingers until it looks like coarse crumbs.","Stir in the 3/4 cup milk just until the dough comes together.","Pat out 3/4 inch thick on a floured counter and cut into 8 biscuits.","Bake on a baking sheet 10 to 12 minutes until golden."]},
s_pancake:{list:["DRY MIX: 3 cups flour","3 tablespoons baking powder","3 tablespoons sugar","1 teaspoon salt","TO COOK 8 PANCAKES: 1 cup mix","1 large egg","3/4 cup milk or water","1 tablespoon oil"],
 steps:["Whisk the 3 cups flour, 3 tablespoons baking powder, 3 tablespoons sugar and 1 teaspoon salt.","Store in a sealed jar up to 3 months.","To cook, whisk 1 cup mix with 1 egg, 3/4 cup milk and 1 tablespoon oil. A few lumps are fine.","Cook 1/4 cup scoops on a greased skillet over medium heat. Flip when bubbles form, about 2 minutes, and cook 1 minute more."]},
s_taco:{list:["2 tablespoons chili powder","1 tablespoon cumin","1 teaspoon garlic powder","1 teaspoon salt","1/2 teaspoon pepper"],
 steps:["Mix the 2 tablespoons chili powder, 1 tablespoon cumin, 1 teaspoon garlic powder, 1 teaspoon salt and 1/2 teaspoon pepper.","Store in a small jar.","Use 2 tablespoons per pound of meat with 2/3 cup water. This batch is about 2 packets."]},
s_ench:{list:["2 tablespoons oil","2 tablespoons flour","2 tablespoons chili powder","1 teaspoon cumin","1/2 teaspoon garlic powder","1 can (8 oz) tomato sauce","1 cup chicken broth (or 1 cup water with 1 teaspoon bouillon)","1/4 teaspoon salt"],
 steps:["Heat the 2 tablespoons oil in a pot over medium heat. Whisk in the 2 tablespoons flour and cook 1 minute.","Stir in the 2 tablespoons chili powder, 1 teaspoon cumin and 1/2 teaspoon garlic powder for 30 seconds.","Whisk in the tomato sauce and 1 cup broth until smooth.","Simmer 10 minutes until slightly thick. Season with the salt. Makes about 2 cups, the same as a 10 oz can plus a little."]},
s_cream:{list:["3 tablespoons butter (or oil)","3 tablespoons flour","1/2 cup milk","1/2 cup chicken broth (or 1/2 cup water with 1/2 teaspoon bouillon)","1/4 teaspoon salt","Pinch of pepper"],
 steps:["Melt the 3 tablespoons butter in a pot over medium heat.","Whisk in the 3 tablespoons flour and cook 1 minute.","Slowly whisk in the 1/2 cup milk, then the 1/2 cup broth.","Stir until thick, about 3 minutes. Season with salt and pepper. This replaces one 10 oz can of cream soup."]},
s_bbq:{list:["1 cup ketchup","1/3 cup sugar (brown sugar is even better)","1 tablespoon mustard","1 tablespoon vinegar","1/4 teaspoon chili powder","1/4 teaspoon garlic powder"],
 steps:["Stir the 1 cup ketchup, 1/3 cup sugar, 1 tablespoon mustard, 1 tablespoon vinegar, chili powder and garlic powder in a small pot.","Simmer over low heat 5 minutes, stirring, until the sugar dissolves.","Cool and keep in the fridge up to 2 weeks. Makes about 1 1/4 cups."]},
s_beans:{list:["1 lb dry pinto beans","1/2 onion, chopped","8 cups water","1 1/2 teaspoons salt"],
 steps:["Pick out any small stones and rinse the beans.","Soak overnight in plenty of water. Or for a quick soak, boil 2 minutes and let sit covered 1 hour.","Drain. Cover with the 8 cups fresh water and add the onion.","Simmer partly covered 1 to 1 1/2 hours until soft, adding water if they get low.","Stir in the 1 1/2 teaspoons salt at the end. Makes about 6 cups, the same as 4 cans."]},
s_broth:{list:["Bones from 1 roast chicken (or 2 lb wings, backs or leg bones)","1/2 onion, quartered","2 carrots, cut in chunks (or carrot peels and ends)","2 stalks celery (or celery ends)","10 to 12 cups water","1 teaspoon salt"],
 steps:["Put the bones and vegetables in a big pot.","Cover with the water, about 2 inches above everything.","Bring to a boil, then turn to low and simmer uncovered 2 to 3 hours. Skim off any foam.","Strain and stir in the 1 teaspoon salt.","Cool, then refrigerate up to 5 days or freeze in 2 cup containers. Makes about 8 cups."]},
s_corntort:{list:["2 cups masa harina","1/4 teaspoon salt","About 1 1/2 cups warm water"],
 steps:["Mix the 2 cups masa harina and salt. Stir in the warm water a little at a time until it feels like soft play dough and does not crack.","Cover and rest 10 minutes.","Roll into 16 balls the size of a golf ball.","Press each flat between 2 pieces of plastic (a cut zip bag works) with the bottom of a heavy pan.","Cook in a dry hot skillet 1 minute per side, until spotted. Stack in a towel to stay soft."]},
s_rolls:{list:["1 packet (2 1/4 teaspoons) yeast","2 tablespoons sugar","1 cup warm milk (about 110°F)","3 cups flour","3 tablespoons butter, melted (or oil)","1 teaspoon salt"],
 steps:["Stir the yeast and 2 tablespoons sugar into the 1 cup warm milk. Wait 5 minutes until foamy.","Add the 3 cups flour, 3 tablespoons melted butter and 1 teaspoon salt.","Knead 6 minutes until smooth and soft.","Cover and let rise 1 hour until doubled.","Shape into 12 balls for rolls, or 8 flattened balls for burger buns. Set on a greased pan, cover and rise 30 minutes.","Bake at 375°F for 15 to 18 minutes until golden."]},
s_flatbread:{list:["2 cups flour","2 teaspoons baking powder","1/2 teaspoon salt","1 cup plain yogurt (or 3/4 cup milk)","1 tablespoon oil, plus a little for the pan"],
 steps:["Mix the 2 cups flour, 2 teaspoons baking powder and 1/2 teaspoon salt.","Stir in the 1 cup yogurt and 1 tablespoon oil into a soft dough.","Knead 1 minute and split into 8 pieces.","Roll each about 1/8 inch thick.","Cook in a lightly oiled hot skillet 1 to 2 minutes per side until puffed and spotted."]},
s_refried:{list:["3 cups cooked pinto beans with 1/2 cup of their liquid (or 2 cans, drained, liquid saved)","1/4 onion, finely chopped","2 tablespoons oil","1/2 teaspoon cumin","1/2 teaspoon chili powder","1/2 teaspoon salt"],
 steps:["Heat the 2 tablespoons oil in a skillet over medium heat. Cook the onion 4 minutes until soft.","Add the beans, cumin and chili powder.","Mash with a potato masher or fork.","Stir in the bean liquid a little at a time until creamy.","Season with the salt. Makes about 3 cups."]},
s_salsa:{list:["1 can (14 oz) diced tomatoes with juice (or 3 fresh tomatoes)","1/4 onion, chopped","1 jalapeño, seeded (or a pinch of chili flakes)","1/2 bunch cilantro","1 lime, juiced","1/2 teaspoon salt"],
 steps:["Put the tomatoes, onion, jalapeño and cilantro in a blender.","Pulse 5 or 6 times until chunky. Or chop everything very fine.","Stir in the lime juice and 1/2 teaspoon salt.","Chill 15 minutes for the flavors to blend. Makes about 2 cups."]},
s_spagsauce:{list:["2 cans (8 oz each) tomato sauce","1 can (6 oz) tomato paste","1/2 onion, diced","1 tablespoon oil","2 teaspoons Italian seasoning","1/2 teaspoon garlic powder","1 teaspoon sugar","1/2 teaspoon salt","1/2 cup water"],
 steps:["Heat the 1 tablespoon oil in a pot over medium heat. Cook the onion 5 minutes.","Stir in the tomato paste and cook 1 minute.","Add the tomato sauce, 1/2 cup water, Italian seasoning, garlic powder, sugar and salt.","Simmer 15 minutes, stirring now and then. Makes about 3 cups, about one jar."]},
s_ranch:{list:["1 cup mayo (or plain yogurt)","1/2 cup milk","2 tablespoons chopped fresh parsley (or 2 teaspoons dried Italian seasoning)","1/2 teaspoon garlic powder","1/4 teaspoon onion powder (optional)","1/4 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Whisk the 1 cup mayo with the 1/2 cup milk until smooth. Use less milk for a thick dip.","Stir in the herbs, garlic powder, onion powder, salt and pepper.","Chill 30 minutes. Keeps 1 week in the fridge."]},
s_italdressing:{list:["1/2 cup oil","1/4 cup vinegar","1 tablespoon Italian seasoning","1/2 teaspoon garlic powder","1 teaspoon sugar","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Put everything in a jar with a lid.","Shake hard 30 seconds.","Shake again before each use. Keeps 2 weeks in the fridge."]},
s_gravy:{list:["3 tablespoons butter (or oil)","3 tablespoons flour","2 cups chicken broth for brown gravy (or 2 cups milk for white gravy)","1/4 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Melt the 3 tablespoons butter in a skillet over medium heat.","Whisk in the 3 tablespoons flour and cook 1 to 2 minutes. Let it turn light brown for brown gravy.","Slowly whisk in the 2 cups broth or milk.","Simmer 3 to 5 minutes, whisking, until thick. Season with salt and pepper."]},
s_alfredo:{list:["3 tablespoons butter","4 oz cream cheese (1/2 block), cubed (or 1/2 can evaporated milk)","1 cup milk","3/4 cup grated parmesan (or shredded mozzarella)","1/2 teaspoon garlic powder","Pinch of pepper"],
 steps:["Melt the 3 tablespoons butter in a pot over medium low heat.","Add the 4 oz cream cheese and 1 cup milk and whisk until smooth.","Stir in the 3/4 cup parmesan and 1/2 teaspoon garlic powder until melted.","Season with pepper. Makes enough for 1 lb of pasta."]},
s_syrup:{list:["1 cup sugar (brown sugar tastes more like maple)","1/2 cup water","1/2 teaspoon vanilla extract (or a pinch of cinnamon)"],
 steps:["Simmer the 1 cup sugar and 1/2 cup water in a small pot over medium heat, stirring, until the sugar dissolves, about 3 minutes.","Simmer 2 minutes more without stirring.","Take off the heat and stir in the vanilla.","It thickens as it cools. Keeps 1 month in the fridge."]},
s_granola:{list:["3 cups old fashioned oats","1/3 cup honey (or brown sugar)","1/4 cup oil","1 teaspoon cinnamon","1/4 teaspoon salt","1/2 cup raisins (or other dried fruit)"],
 steps:["Heat oven to 325°F. Line a baking sheet with parchment.","Warm the 1/3 cup honey and 1/4 cup oil together, then stir in the cinnamon and salt.","Toss with the 3 cups oats until coated.","Spread on the sheet and press down a little to make clusters.","Bake 20 to 25 minutes, stirring once, until golden.","Cool completely, then stir in the raisins."]},
s_breadcrumbs:{list:["4 slices stale bread or bread heels","1 teaspoon Italian seasoning (optional)"],
 steps:["Toast the bread in a toaster or a 300°F oven for 10 minutes until fully dry.","Cool, then crush in a zip bag with a rolling pin or blend until fine.","Stir in the Italian seasoning if you like. Makes about 1 cup."]},
s_croutons:{list:["4 slices day old bread, cut into 3/4 inch cubes","2 tablespoons oil","1/2 teaspoon Italian seasoning","1/4 teaspoon garlic powder","Pinch of salt"],
 steps:["Heat oven to 375°F.","Toss the bread cubes with the 2 tablespoons oil, Italian seasoning, garlic powder and salt.","Spread on a baking sheet.","Bake 10 to 12 minutes, stirring once, until crisp. Makes about 2 cups."]},
s_yogurt:{list:["1/2 gallon (8 cups) milk","1/4 cup plain yogurt with live cultures"],
 steps:["Heat the milk in a large pot over medium heat to 180°F, when it steams and tiny bubbles form at the edge. Stir so it does not scorch.","Cool to 110°F, warm to the touch. Setting the pot in cold water speeds this up.","Whisk the 1/4 cup yogurt with a cup of the warm milk, then stir it back into the pot.","Cover and keep warm 8 to 10 hours. An oven with just the light on works.","Refrigerate at least 4 hours. Makes about 8 cups. Save 1/4 cup for the next batch."]},
s_brownies:{list:["1/2 cup (1 stick) butter, melted (or 1/2 cup oil)","1 cup sugar","2 large eggs","1 teaspoon vanilla extract","1/2 cup flour","1/3 cup cocoa powder","1/4 teaspoon salt","1/4 teaspoon baking powder"],
 steps:["Heat oven to 350°F. Grease an 8x8 pan.","Stir the melted butter and 1 cup sugar, then beat in the 2 eggs and 1 teaspoon vanilla.","Stir in the 1/2 cup flour, 1/3 cup cocoa, salt and baking powder until just mixed.","Spread in the pan and bake 22 to 25 minutes until a toothpick comes out with moist crumbs.","Cool before cutting into 16 squares."]},
s_muffins:{list:["2 cups flour","2 teaspoons baking powder","1/2 cup sugar","1/2 teaspoon salt","1 large egg","3/4 cup milk","1/3 cup oil","1 cup frozen berries (or 2 mashed ripe bananas)"],
 steps:["Heat oven to 400°F. Line or grease a 12 cup muffin pan.","Whisk the 2 cups flour, 2 teaspoons baking powder, 1/2 cup sugar and 1/2 teaspoon salt.","In another bowl, whisk the egg, 3/4 cup milk and 1/3 cup oil.","Stir the wet into the dry just until mixed. Lumps are fine.","Fold in the berries or bananas.","Fill the cups 2/3 full and bake 18 to 20 minutes until golden."]},
s_pudding:{list:["3 cups milk","1/2 cup sugar","1/4 cup flour","1/4 teaspoon salt","2 large eggs, beaten","1 teaspoon vanilla extract"],
 steps:["Whisk the 1/2 cup sugar, 1/4 cup flour and salt in a pot, then whisk in the 3 cups milk.","Cook over medium heat, stirring constantly, until it thickens and bubbles, about 8 minutes.","Whisk 1/2 cup of the hot pudding into the beaten eggs, then stir the egg mix back into the pot.","Cook 1 to 2 minutes more, stirring.","Take off the heat and stir in the 1 teaspoon vanilla. Cover the surface with plastic wrap and chill 2 hours. Makes about 3 1/2 cups."]},
s_piecrust:{list:["1 1/4 cups flour","1/4 teaspoon salt","1/2 cup (1 stick) cold butter, cut in small cubes","3 to 4 tablespoons ice water"],
 steps:["Mix the 1 1/4 cups flour and 1/4 teaspoon salt.","Rub in the cold butter with your fingers or a fork until it looks like coarse crumbs with some pea sized bits.","Sprinkle in the ice water 1 tablespoon at a time, stirring, until the dough holds together when squeezed.","Press into a disk, wrap and chill 30 minutes.","Roll out on a floured counter into an 11 inch circle for a 9 inch pie pan. Makes 1 crust."]},
s_wrappers:{list:["2 cups flour, plus more for rolling","1/4 teaspoon salt","About 3/4 cup hot water"],
 steps:["Mix the 2 cups flour and salt. Stir in the hot water a little at a time until a firm dough forms.","Knead 5 minutes until smooth.","Cover and rest 30 minutes.","Roll into a long log and cut into 30 pieces.","Roll each piece into a thin 3 1/2 inch circle on a floured counter. Keep them covered so they do not dry out."]},
s_condmilk:{list:["2 cups milk","2/3 cup sugar","1 tablespoon butter","1/2 teaspoon vanilla extract (optional)"],
 steps:["Stir the 2 cups milk and 2/3 cup sugar in a heavy pot over medium heat until the sugar dissolves.","Turn to low and simmer, stirring often, about 30 to 40 minutes until it reduces by half to about 1 1/4 cups.","Stir in the 1 tablespoon butter and vanilla.","It thickens as it cools. This replaces one 14 oz can."]}
});
